import React, { useMemo, useState, useCallback } from "react"

import Panel from "../layout/Panel"
import EquityCurve from "./EquityCurve"
import { STRATEGIES, getStrategy, paramControls } from "../../engine/strategy.js"
import { runBacktest, baselineMetrics } from "../../engine/browserBacktest.js"

/**
 * Edit a strategy's parameters and re-run its backtest.
 *
 * This page used to be read-only: it showed what the engine concluded at build
 * time and gave you no way to ask it anything else. The engine itself was
 * always capable of more — what was missing was a surface.
 *
 * THE THING THIS UI HAS TO GET RIGHT
 * Letting somebody tune parameters against a fixed history and watch the
 * return climb is a machine for producing overfitted nonsense. The page's whole
 * editorial line is that an in-sample number is not evidence, and a control
 * panel that quietly contradicted it would do more harm than not existing.
 *
 * So the framing is structural rather than a note somebody might skip. The
 * build-time baseline and a live run are shown as separate columns with
 * different labels; the baseline is the one with a walk-forward result behind
 * it; and the moment a parameter is changed, the result is marked in-sample
 * and stays marked. The number is never presented as a finding.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)
const pct = (v, d = 2) => (isNum(v) ? (v > 0 ? "+" : "") + v.toFixed(d) + "%" : DASH)
const num = (v, d = 2) => (isNum(v) ? v.toFixed(d) : DASH)
const usd = v => (isNum(v) ? (v < 0 ? "−$" : "$") + Math.abs(v).toFixed(0) : DASH)

/** Compact money, so a liquidity floor reads as "5M" rather than 5000000. */
function compact(v) {
  if (!isNum(v)) return ""
  if (Math.abs(v) >= 1e9) return (v / 1e9).toFixed(v % 1e9 === 0 ? 0 : 1) + "B"
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(v % 1e6 === 0 ? 0 : 1) + "M"
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(v % 1e3 === 0 ? 0 : 1) + "K"
  return String(v)
}

/** Direction that counts as an improvement for each metric. */
const BETTER = {
  trades: 0,
  totalReturnPct: 1,
  maxDrawdownPct: -1,
  winRate: 1,
  profitFactor: 1,
  expectancy: 1,
  sharpe: 1,
}

const ROWS = [
  { key: "trades", label: "Trades", fmt: v => (isNum(v) ? String(v) : DASH) },
  { key: "totalReturnPct", label: "Return", fmt: v => pct(v, 2) },
  { key: "maxDrawdownPct", label: "Max drawdown", fmt: v => num(v, 1) + "%" },
  { key: "winRate", label: "Win rate", fmt: v => num(v, 0) + "%" },
  { key: "profitFactor", label: "Profit factor", fmt: v => num(v, 2) },
  { key: "expectancy", label: "Expectancy", fmt: usd },
  { key: "sharpe", label: "Sharpe", fmt: v => num(v, 2) },
]

export default function StrategyLab({ backtests, symbols, timeframe = "5Y", onNotice }) {
  const [strategyId, setStrategyId] = useState(STRATEGIES[0]?.id ?? null)
  const [edited, setEdited] = useState({})
  const [result, setResult] = useState(null)
  const [running, setRunning] = useState(false)
  const [error, setError] = useState(null)

  const strategy = useMemo(() => getStrategy(strategyId), [strategyId])
  const controls = useMemo(() => (strategy ? paramControls(strategy) : []), [strategy])

  const baseline = useMemo(
    () => baselineMetrics(backtests.find(b => b.strategyId === strategyId)),
    [backtests, strategyId]
  )

  /** Current value for a control — the edit if there is one, else the default. */
  const valueOf = key => (key in edited ? edited[key] : strategy?.params?.[key])

  const dirty = useMemo(
    () => controls.some(c => valueOf(c.key) !== strategy?.params?.[c.key]),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [edited, controls, strategy]
  )

  const selectStrategy = id => {
    setStrategyId(id)
    // Edits belong to the strategy they were made against. Carrying an RSI
    // level onto a breakout strategy would silently apply a number that means
    // something different, or nothing at all.
    setEdited({})
    setResult(null)
    setError(null)
  }

  const run = useCallback(() => {
    if (!strategy) return
    setRunning(true)
    setError(null)

    /*
     * Deferred a frame so the button can paint its busy state before the
     * engine blocks the thread. A portfolio pass is ~70ms — short enough not
     * to need a worker, long enough that a synchronous call would swallow the
     * feedback and make the click feel ignored.
     */
    requestAnimationFrame(() => {
      try {
        const next = runBacktest({ strategyId: strategy.id, params: edited, symbols, timeframe })
        if (!next.ok) {
          setError(next.message || "The backtest could not run.")
          setResult(null)
        } else {
          setResult(next)
          if (next.clamped.length && onNotice) {
            const names = next.clamped
              .map(k => controls.find(c => c.key === k)?.label || k)
              .join(", ")
            onNotice(`Out of range, so the nearest allowed value was used: ${names}.`)
          }
        }
      } catch (e) {
        setError(e.message || String(e))
        setResult(null)
      } finally {
        setRunning(false)
      }
    })
  }, [strategy, edited, symbols, timeframe, controls, onNotice])

  const reset = () => {
    setEdited({})
    setResult(null)
    setError(null)
  }

  if (!strategy) return null

  const live = result ? baselineMetrics({ analysis: result.analysis }) : null

  return (
    <Panel
      title="Parameter lab"
      subtitle="Change a rule, re-run the same engine, compare against the baseline"
    >
      <div className="lab">

        {/* ------------------------------------------------------ strategy */}
        <div className="lab__strategies" role="tablist" aria-label="Strategy">
          {STRATEGIES.map(s => (
            <button
              key={s.id}
              type="button"
              role="tab"
              aria-selected={s.id === strategyId}
              className={"lab__tab" + (s.id === strategyId ? " is-active" : "")}
              onClick={() => selectStrategy(s.id)}
            >
              {s.name}
            </button>
          ))}
        </div>

        <p className="lab__desc">{strategy.description}</p>

        {/* -------------------------------------------------------- params */}
        <div className="lab__params">
          {controls.map(control => {
            const value = valueOf(control.key)
            const changed = value !== strategy.params[control.key]

            return (
              <div className={"lab__param" + (changed ? " is-changed" : "")} key={control.key}>
                <label className="lab__label" htmlFor={`p-${strategy.id}-${control.key}`}>
                  {control.label}
                  {changed && <span className="lab__changed-dot" aria-label="changed" />}
                </label>

                {control.type === "boolean" ? (
                  <label className="lab__switch">
                    <input
                      id={`p-${strategy.id}-${control.key}`}
                      type="checkbox"
                      checked={Boolean(value)}
                      onChange={e => setEdited(p => ({ ...p, [control.key]: e.target.checked }))}
                    />
                    <span>{value ? "Yes" : "No"}</span>
                  </label>
                ) : (
                  <div className="lab__number">
                    <input
                      id={`p-${strategy.id}-${control.key}`}
                      type="number"
                      className="lab__input"
                      value={value === null ? "" : value}
                      min={control.min}
                      max={control.max}
                      step={control.step}
                      placeholder={control.nullable ? "none" : undefined}
                      onChange={e => {
                        const raw = e.target.value
                        setEdited(p => ({
                          ...p,
                          [control.key]: raw === "" ? (control.nullable ? null : "") : Number(raw),
                        }))
                      }}
                    />
                    <span className="lab__range">
                      {control.format === "compact"
                        ? `${compact(control.min)}–${compact(control.max)}`
                        : `${control.min}–${control.max}`}
                    </span>
                  </div>
                )}

                {control.help && <p className="lab__help">{control.help}</p>}
              </div>
            )
          })}
        </div>

        {/* ------------------------------------------------------- actions */}
        <div className="lab__actions">
          <button
            type="button"
            className="lab__btn lab__btn--primary"
            onClick={run}
            disabled={running}
          >
            {running ? "Running…" : "Run backtest"}
          </button>
          <button type="button" className="lab__btn" onClick={reset} disabled={!dirty && !result}>
            Reset to defaults
          </button>
          {dirty && !result && <span className="lab__hint">Changed — run to see the effect</span>}
          {result && (
            <span className="lab__hint">
              {result.symbols.length} symbols · {result.timeframe} · {result.tookMs}ms
            </span>
          )}
        </div>

        {error && <p className="lab__error">{error}</p>}

        {/* ------------------------------------------------------- results */}
        {result && (
          <>
            <div className="lab__compare">
              <table className="lab__table">
                <thead>
                  <tr>
                    <th />
                    <th>
                      Baseline
                      <span className="lab__th-note">walk-forward tested</span>
                    </th>
                    <th>
                      Your run
                      <span className="lab__th-note lab__th-note--warn">in-sample only</span>
                    </th>
                    <th>Change</th>
                  </tr>
                </thead>
                <tbody>
                  {ROWS.map(row => {
                    const b = baseline?.[row.key]
                    const l = live?.[row.key]
                    const delta = isNum(b) && isNum(l) ? l - b : null
                    const dir = BETTER[row.key] || 0
                    const better = isNum(delta) && dir !== 0 ? delta * dir > 0 : null

                    return (
                      <tr key={row.key}>
                        <th scope="row">{row.label}</th>
                        <td>{row.fmt(b)}</td>
                        <td className="is-live">{row.fmt(l)}</td>
                        <td
                          className={
                            "lab__delta" +
                            (better === true ? " is-better" : better === false ? " is-worse" : "")
                          }
                        >
                          {isNum(delta)
                            ? (delta > 0 ? "+" : "") + delta.toFixed(row.key === "trades" ? 0 : 2)
                            : DASH}
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>

            {/*
              The warning is attached to the result, not parked in a footer.
              It appears the moment a tuned number does, because that is the
              moment somebody is most likely to believe it.
            */}
            {result.modified && (
              <div className="lab__warning">
                <strong>These parameters were chosen after seeing this data.</strong> That is
                what overfitting is, and it is why the figure above is labelled in-sample.
                The baseline beside it earned its claim by being tested on data the optimiser
                never saw; this run has been tested on nothing. A better number here is a
                hypothesis, not a result — it means something only once it survives a
                walk-forward pass it did not help choose.
              </div>
            )}

            <div className="lab__curve">
              <EquityCurve
                points={result.equityCurve}
                initial={result.equityCurve[0]?.equity}
              />
            </div>

            {result.analysis.caveats?.length > 0 && (
              <ul className="lab__caveats">
                {result.analysis.caveats.map((c, i) => (
                  <li key={i}>{c}</li>
                ))}
              </ul>
            )}

            {result.trades.length === 0 && (
              <p className="lab__empty">
                These parameters produced <strong>no trades</strong> — the entry conditions were
                never all true at once. That is a real answer, not a failure: tightening a filter
                far enough always ends here.
              </p>
            )}
          </>
        )}
      </div>
    </Panel>
  )
}
