/**
 * Feature engineering — the single source of derived numbers.
 *
 * THE RULE THAT MAKES A BACKTEST HONEST: every feature at index `i` is computed
 * from bars[0..i] ONLY. Nothing here may read bars[i+1] or later, directly or
 * through a helper that scans the whole array. A backtest that leaks one future
 * bar produces a beautiful equity curve and loses money in production, and the
 * leak is almost impossible to spot after the fact — so it is prevented here, at
 * the only place features are produced.
 *
 * The scanner, the signal engine and the backtester all call THIS module. If
 * they each had their own momentum calculation, a strategy that backtested well
 * would not be the strategy the scanner runs.
 */

import { ema, rsi, macd, atr, sma } from "../data/indicators.js"
import {
  sessionVwap,
  rollingVwap,
  sessionProfile,
  hasExchangeVwap,
  distancePct,
  vwapZScore,
} from "./vwap.js"

/* --------------------------------------------------------------------------
   Small helpers. All of them return null rather than NaN, so "not computable
   yet" stays distinguishable from "computed as zero".
   -------------------------------------------------------------------------- */

function pctChange(from, to) {
  if (!Number.isFinite(from) || !Number.isFinite(to) || from === 0) return null
  return ((to - from) / Math.abs(from)) * 100
}

function mean(values) {
  if (!values.length) return null
  let sum = 0
  for (const v of values) sum += v
  return sum / values.length
}

function stdev(values) {
  if (values.length < 2) return null
  const m = mean(values)
  let acc = 0
  for (const v of values) acc += (v - m) ** 2
  return Math.sqrt(acc / (values.length - 1))
}

/** Highest high over the window ENDING at index i (inclusive). */
function highestHigh(bars, i, window) {
  const start = Math.max(0, i - window + 1)
  let h = -Infinity
  for (let k = start; k <= i; k += 1) if (bars[k].high > h) h = bars[k].high
  return Number.isFinite(h) ? h : null
}

function lowestLow(bars, i, window) {
  const start = Math.max(0, i - window + 1)
  let l = Infinity
  for (let k = start; k <= i; k += 1) if (bars[k].low < l) l = bars[k].low
  return Number.isFinite(l) ? l : null
}

const TRADING_DAYS = 252

/* --------------------------------------------------------------------------
   The feature set
   -------------------------------------------------------------------------- */

/**
 * Precomputes the full-length indicator arrays a feature pass needs.
 *
 * These are computed ONCE over the whole series and then sampled at index i.
 * That is safe because every indicator here is causal — index i of an EMA
 * depends only on bars up to i — so sampling is identical to recomputing on a
 * prefix, at a fraction of the cost. Any non-causal indicator added later MUST
 * NOT be precomputed this way.
 */
export function prepare(bars) {
  const closes = bars.map(b => b.close)
  const volumes = bars.map(b => b.volume)
  return {
    bars,
    closes,
    volumes,
    ema9: ema(closes, 9),
    ema20: ema(closes, 20),
    ema50: ema(closes, 50),
    ema200: ema(closes, 200),
    rsi14: rsi(closes, 14),
    macd: macd(closes, 12, 26, 9),
    atr14: atr(bars, 14),
    volSma20: sma(volumes, 20),
    volSma50: sma(volumes, 50),

    /*
     * VWAP. Session-anchored (resets each New York trading day) plus a
     * 20-bar rolling volume-weighted average.
     *
     * On a DAILY series one bar IS one session, so the session VWAP equals
     * that bar's own volume-weighted price by definition — arithmetically
     * correct, and not very useful. "vwap20" is the meaningful daily figure.
     * On INTRADAY bars the session VWAP is the real accumulating one, and
     * "vwapProfile.intraday" says which case the caller is in, so nothing
     * downstream has to guess.
     */
    vwap: sessionVwap(bars),
    vwap20: rollingVwap(bars, 20),
    vwapProfile: sessionProfile(bars),
    vwapIsExchange: hasExchangeVwap(bars),
  }
}

/**
 * The feature vector at one bar.
 *
 * @param {object} ctx  the result of prepare()
 * @param {number} i    bar index. Only bars[0..i] are read.
 */
export function featuresAt(ctx, i) {
  const { bars, closes } = ctx
  if (i < 0 || i >= bars.length) return null

  const bar = bars[i]
  const close = bar.close

  /* ---- Returns ---- */
  const ret1 = i >= 1 ? pctChange(closes[i - 1], close) : null
  const ret5 = i >= 5 ? pctChange(closes[i - 5], close) : null
  const ret20 = i >= 20 ? pctChange(closes[i - 20], close) : null
  const ret60 = i >= 60 ? pctChange(closes[i - 60], close) : null

  /* ---- Volatility: stdev of the last 20 daily returns, annualised ---- */
  let vol20 = null
  if (i >= 21) {
    const rets = []
    for (let k = i - 19; k <= i; k += 1) {
      const r = pctChange(closes[k - 1], closes[k])
      if (r !== null) rets.push(r)
    }
    const sd = stdev(rets)
    vol20 = sd === null ? null : sd * Math.sqrt(TRADING_DAYS)
  }

  /* ---- Range ---- */
  const range = bar.high - bar.low
  const rangePct = close > 0 ? (range / close) * 100 : null
  // Where in the bar's own range it closed: 1 = on the high, 0 = on the low.
  const closeLocation = range > 0 ? (close - bar.low) / range : null

  /* ---- Volume ---- */
  const volSma20 = ctx.volSma20[i]
  const rvol = volSma20 && volSma20 > 0 ? bar.volume / volSma20 : null
  const volumeTrend =
    ctx.volSma20[i] !== null && ctx.volSma50[i] !== null && ctx.volSma50[i] > 0
      ? ctx.volSma20[i] / ctx.volSma50[i]
      : null
  // Dollar volume is the real liquidity measure; share count alone flatters
  // penny stocks and penalises high-priced ones.
  const dollarVolume = close * bar.volume

  /* ---- Trend ---- */
  const e9 = ctx.ema9[i]
  const e20 = ctx.ema20[i]
  const e50 = ctx.ema50[i]
  const e200 = ctx.ema200[i]
  const emaSlope20 =
    i >= 5 && ctx.ema20[i] !== null && ctx.ema20[i - 5] !== null
      ? pctChange(ctx.ema20[i - 5], ctx.ema20[i])
      : null

  let trendScore = null
  if (e9 !== null && e20 !== null && e50 !== null) {
    // -3..+3: how many of the stacking conditions hold.
    let score = 0
    score += e9 > e20 ? 1 : -1
    score += e20 > e50 ? 1 : -1
    score += close > e20 ? 1 : -1
    trendScore = score
  }

  /* ---- Position within recent range ---- */
  const high20 = highestHigh(bars, i, 20)
  const low20 = lowestLow(bars, i, 20)
  const high52 = highestHigh(bars, i, TRADING_DAYS)
  const low52 = lowestLow(bars, i, TRADING_DAYS)

  const distFromHigh20 = high20 ? pctChange(high20, close) : null
  const distFromLow20 = low20 ? pctChange(low20, close) : null
  const distFromHigh52 = high52 ? pctChange(high52, close) : null
  const pctOf52wRange =
    high52 !== null && low52 !== null && high52 > low52
      ? ((close - low52) / (high52 - low52)) * 100
      : null

  /* ---- Breakout ---- *
   * The prior high EXCLUDES today, otherwise "today closed above the highest
   * high including today" is true on every up day and means nothing.
   */
  const priorHigh20 = i >= 1 ? highestHigh(bars, i - 1, 20) : null
  const priorLow20 = i >= 1 ? lowestLow(bars, i - 1, 20) : null
  const breakoutAbove20 = priorHigh20 !== null ? close > priorHigh20 : null
  const breakdownBelow20 = priorLow20 !== null ? close < priorLow20 : null
  const breakoutMargin = priorHigh20 !== null ? pctChange(priorHigh20, close) : null

  let daysSinceHigh20 = null
  if (high20 !== null) {
    for (let k = i; k >= Math.max(0, i - 19); k -= 1) {
      if (bars[k].high === high20) {
        daysSinceHigh20 = i - k
        break
      }
    }
  }

  /* ---- Gap ---- */
  const gapPct = i >= 1 ? pctChange(closes[i - 1], bar.open) : null

  /* ---- VWAP ----
   * Session-anchored, plus the 20-bar rolling figure. Both are read from the
   * arrays prepare() built, so a bar's VWAP is accumulated only from bars at
   * or before it within its own session — the same no-look-ahead rule as
   * everything above.
   *
   * `vwapDistPct` is the number traders actually act on ("2% above VWAP"),
   * and `vwapZ` is that distance in volume-weighted standard deviations, which
   * is what separates "barely above" from "stretched".
   */
  const vwapValue = ctx.vwap.vwap[i]
  const vwapSigma = ctx.vwap.sigma[i]
  const vwap20Value = ctx.vwap20[i]

  return {
    index: i,
    time: bar.time,
    open: bar.open,
    high: bar.high,
    low: bar.low,
    close,
    volume: bar.volume,

    ret1,
    ret5,
    ret20,
    ret60,
    vol20,
    rangePct,
    closeLocation,
    gapPct,

    volume20: volSma20,
    rvol,
    volumeTrend,
    dollarVolume,

    ema9: e9,
    ema20: e20,
    ema50: e50,
    ema200: e200,
    emaSlope20,
    trendScore,
    rsi14: ctx.rsi14[i],
    macd: ctx.macd.macd[i],
    macdSignal: ctx.macd.signal[i],
    macdHistogram: ctx.macd.histogram[i],
    atr14: ctx.atr14[i],
    atrPct: ctx.atr14[i] !== null && close > 0 ? (ctx.atr14[i] / close) * 100 : null,

    high20,
    low20,
    high52,
    low52,
    distFromHigh20,
    distFromLow20,
    distFromHigh52,
    pctOf52wRange,

    priorHigh20,
    priorLow20,
    breakoutAbove20,
    breakdownBelow20,
    breakoutMargin,
    daysSinceHigh20,

    /* ---- VWAP ---- */
    vwap: vwapValue,
    vwapDistPct: distancePct(close, vwapValue),
    aboveVwap: vwapValue === null ? null : close > vwapValue,
    vwapSigma,
    vwapZ: vwapZScore(close, vwapValue, vwapSigma),
    vwapUpper1: ctx.vwap.upper1[i],
    vwapLower1: ctx.vwap.lower1[i],
    vwapUpper2: ctx.vwap.upper2[i],
    vwapLower2: ctx.vwap.lower2[i],
    /** Position within the session, 0-based. 0 on every bar of a daily series. */
    vwapBarInSession: ctx.vwap.barIndex[i],

    vwap20: vwap20Value,
    vwapDist20Pct: distancePct(close, vwap20Value),
    aboveVwap20: vwap20Value === null ? null : close > vwap20Value,
  }
}

/** Feature vectors for every bar, aligned to the input array. */
export function featureSeries(bars) {
  if (!Array.isArray(bars) || !bars.length) return []
  const ctx = prepare(bars)
  const out = new Array(bars.length)
  for (let i = 0; i < bars.length; i += 1) out[i] = featuresAt(ctx, i)
  return out
}

/** Convenience: the feature vector at the most recent bar. */
export function latestFeatures(bars) {
  if (!Array.isArray(bars) || !bars.length) return null
  const ctx = prepare(bars)
  return featuresAt(ctx, bars.length - 1)
}

/**
 * Every feature this module produces, with a human label and the unit.
 * The scanner builds its filter list from this rather than hardcoding a
 * parallel one that can drift.
 */
