/**
 * Portfolio engine — cash, positions, exposure and P&L.
 *
 * Extracted so the SAME object models a backtest and a paper-trading account.
 * If the backtester kept its own notion of a position, a strategy that behaved
 * one way in simulation could behave differently live, and the backtest would
 * stop being evidence about anything.
 *
 * Pure state plus pure transitions: no clock, no RNG, no I/O. Time is always
 * passed in. That is what makes a backtest reproducible and a paper session
 * auditable.
 */

export const DEFAULT_PORTFOLIO_CONFIG = {
  initialCash: 100000,
  /** Fraction of CURRENT EQUITY committed to one new position. */
  positionSizePct: 0.1,
  /** Hard cap on simultaneous open positions. */
  maxPositions: 5,
  /** Hard cap on the fraction of equity invested at once. */
  maxExposurePct: 0.9,
  /** No single position may exceed this fraction of equity. */
  maxConcentrationPct: 0.25,
  commissionPerShare: 0.005,
  minCommission: 1,
  slippagePct: 0.0005,
  allowShort: false,
}

export function commissionFor(shares, config) {
  return Math.max(config.minCommission, Math.abs(shares) * config.commissionPerShare)
}

export function createPortfolio(config = {}) {
  const cfg = { ...DEFAULT_PORTFOLIO_CONFIG, ...config }
  return {
    config: cfg,
    cash: cfg.initialCash,
    initialCash: cfg.initialCash,
    positions: new Map(),
    closedTrades: [],
    realizedPnl: 0,
    totalFees: 0,
    /** Last mark price seen per symbol, so equity can be computed any time. */
    marks: new Map(),
    history: [],
  }
}

/* --------------------------------------------------------------------------
   Valuation
   -------------------------------------------------------------------------- */

export function positionValue(portfolio, symbol) {
  const pos = portfolio.positions.get(symbol)
  if (!pos) return 0
  const mark = portfolio.marks.get(symbol)
  return pos.shares * (Number.isFinite(mark) ? mark : pos.entryPrice)
}

export function exposure(portfolio) {
  let total = 0
  for (const symbol of portfolio.positions.keys()) total += positionValue(portfolio, symbol)
  return total
}

export function equity(portfolio) {
  return portfolio.cash + exposure(portfolio)
}

export function unrealizedPnl(portfolio) {
  let total = 0
  for (const [symbol, pos] of portfolio.positions) {
    const mark = portfolio.marks.get(symbol)
    if (!Number.isFinite(mark)) continue
    total += (mark - pos.entryPrice) * pos.shares
  }
  return total
}

/** Records the latest price for a symbol so valuation stays current. */
export function mark(portfolio, symbol, price) {
  if (Number.isFinite(price)) portfolio.marks.set(symbol, price)
}

export function markAll(portfolio, priceBySymbol) {
  for (const [symbol, price] of Object.entries(priceBySymbol)) mark(portfolio, symbol, price)
}

/* --------------------------------------------------------------------------
   Sizing and admission
   -------------------------------------------------------------------------- */

/**
 * How many shares a new position would take, given current equity.
 * Returns 0 when the position would be too small to be worth the commission.
 */
export function sizePosition(portfolio, price, overrideFraction) {
  if (!Number.isFinite(price) || price <= 0) return 0
  const cfg = portfolio.config
  const fraction = Number.isFinite(overrideFraction) ? overrideFraction : cfg.positionSizePct
  const budget = equity(portfolio) * fraction
  const affordable = Math.min(budget, portfolio.cash)
  const shares = Math.floor(affordable / price)
  if (shares <= 0) return 0
  // A position whose commission is a meaningful share of its value is noise.
  const notional = shares * price
  if (commissionFor(shares, cfg) > notional * 0.01) return 0
  return shares
}

/**
 * Whether a new position is admissible, and if not, exactly why.
 *
 * Every rejection carries a machine-readable `code` and a human `reason`, so a
 * rejected trade is auditable rather than silently absent from the results.
 */
export function canOpen(portfolio, symbol, price, shares) {
  const cfg = portfolio.config
  const eq = equity(portfolio)

  if (portfolio.positions.has(symbol)) {
    return { allowed: false, code: "ALREADY_OPEN", reason: `Already holding ${symbol}` }
  }
  if (!Number.isFinite(price) || price <= 0) {
    return { allowed: false, code: "BAD_PRICE", reason: `No usable price for ${symbol}` }
  }
  if (!Number.isFinite(shares) || shares <= 0) {
    return { allowed: false, code: "SIZE_ZERO", reason: "Position size rounded to zero shares" }
  }
  if (portfolio.positions.size >= cfg.maxPositions) {
    return {
      allowed: false,
      code: "MAX_POSITIONS",
      reason: `Already holding ${portfolio.positions.size} of a maximum ${cfg.maxPositions}`,
    }
  }

  const notional = shares * price
  const fee = commissionFor(shares, cfg)
  if (notional + fee > portfolio.cash) {
    return {
      allowed: false,
      code: "INSUFFICIENT_CASH",
      reason: `Needs $${(notional + fee).toFixed(2)}, cash is $${portfolio.cash.toFixed(2)}`,
    }
  }

  if (eq > 0 && (exposure(portfolio) + notional) / eq > cfg.maxExposurePct) {
    return {
      allowed: false,
      code: "MAX_EXPOSURE",
      reason: `Would take exposure past ${(cfg.maxExposurePct * 100).toFixed(0)}% of equity`,
    }
  }
  if (eq > 0 && notional / eq > cfg.maxConcentrationPct) {
    return {
      allowed: false,
      code: "MAX_CONCENTRATION",
      reason: `Single position would be ${((notional / eq) * 100).toFixed(1)}% of equity, limit ${(cfg.maxConcentrationPct * 100).toFixed(0)}%`,
    }
  }

  return { allowed: true, code: "OK", reason: "Within limits" }
}

/* --------------------------------------------------------------------------
   Transitions
   -------------------------------------------------------------------------- */

export function openPosition(portfolio, { symbol, shares, price, time, reason, meta }) {
  const cfg = portfolio.config
  const fee = commissionFor(shares, cfg)
  const cost = shares * price + fee

  if (cost > portfolio.cash) {
    return { ok: false, code: "INSUFFICIENT_CASH", reason: "Cash moved before the fill" }
  }

  portfolio.cash -= cost
  portfolio.totalFees += fee
  const position = {
    symbol,
    shares,
    entryPrice: price,
    entryTime: time,
    entryFee: fee,
    entryReason: reason || null,
    stop: null,
    target: null,
    barsHeld: 0,
    meta: meta || null,
  }
  portfolio.positions.set(symbol, position)
  mark(portfolio, symbol, price)
  portfolio.history.push({ type: "open", symbol, shares, price, time, fee, reason })
  return { ok: true, position }
}

export function closePosition(portfolio, { symbol, price, time, reason }) {
  const pos = portfolio.positions.get(symbol)
  if (!pos) return { ok: false, code: "NO_POSITION", reason: `No open position in ${symbol}` }

  const cfg = portfolio.config
  const fee = commissionFor(pos.shares, cfg)
  const proceeds = pos.shares * price - fee
  portfolio.cash += proceeds
  portfolio.totalFees += fee

  const gross = (price - pos.entryPrice) * pos.shares
  const net = gross - pos.entryFee - fee
  portfolio.realizedPnl += net

  const trade = {
    symbol,
    shares: pos.shares,
    entryTime: pos.entryTime,
    entryPrice: pos.entryPrice,
    entryReason: pos.entryReason,
    exitTime: time,
    exitPrice: price,
    exitReason: reason || null,
    barsHeld: pos.barsHeld,
    grossPnl: gross,
    fees: pos.entryFee + fee,
    pnl: net,
    returnPct: pos.entryPrice > 0 ? (net / (pos.entryPrice * pos.shares)) * 100 : 0,
    entryFeatures: pos.meta ? pos.meta.features || null : null,
  }
  portfolio.closedTrades.push(trade)
  portfolio.positions.delete(symbol)
  portfolio.history.push({ type: "close", symbol, shares: pos.shares, price, time, fee, reason })
  return { ok: true, trade }
}

/** A point-in-time view, safe to serialise into the audit log. */
export function snapshot(portfolio, time) {
  return {
    time: time ?? null,
    cash: portfolio.cash,
    equity: equity(portfolio),
    exposure: exposure(portfolio),
    exposurePct: equity(portfolio) > 0 ? (exposure(portfolio) / equity(portfolio)) * 100 : 0,
    realizedPnl: portfolio.realizedPnl,
    unrealizedPnl: unrealizedPnl(portfolio),
    totalFees: portfolio.totalFees,
    openPositions: [...portfolio.positions.values()].map(p => ({
      symbol: p.symbol,
      shares: p.shares,
      entryPrice: p.entryPrice,
      mark: portfolio.marks.get(p.symbol) ?? p.entryPrice,
      unrealized: ((portfolio.marks.get(p.symbol) ?? p.entryPrice) - p.entryPrice) * p.shares,
    })),
    closedTrades: portfolio.closedTrades.length,
  }
}
