/**
 * Risk engine — the gate between a strategy signal and a portfolio action.
 *
 * A strategy answers "is this a setup?". It does not get to answer "how much?".
 * That second question belongs here, because position size is where accounts
 * actually die: a correct strategy sized wrongly still goes to zero, and no
 * amount of edge survives one position large enough to matter.
 *
 * TWO THINGS THIS MODULE EXISTS TO ENFORCE
 *
 * 1. RISK-BASED SIZING, NOT FIXED FRACTIONAL SIZING.
 *    Fixed fractional sizing says "put 10% of equity into every trade". The
 *    dollar loss is then whatever the stop happens to be: a trade stopped 2%
 *    away loses 0.2% of the account, a trade stopped 15% away loses 1.5% —
 *    more than seven times as much, from the same signal, with nobody ever
 *    having decided that. Risk-based sizing inverts the arithmetic. The dollar
 *    loss is fixed FIRST and the share count is derived from the stop:
 *
 *        shares = floor(equity * riskPerTradePct / (entry - stop))
 *
 *    A WIDE STOP THEREFORE BUYS FEWER SHARES. The loss when the stop is hit is
 *    the same for every trade, so a losing streak costs a predictable amount
 *    instead of depending on which volatility regime the losers happened to
 *    land in. The position cap, concentration cap, exposure cap and available
 *    cash then only ever REDUCE that share count; nothing here can raise it.
 *
 * 2. EVERY DECISION IS AUDITABLE. assess() returns every check that ran —
 *    passed or failed — with a machine code and a human sentence. A trade that
 *    did not happen leaves a record saying why. Without that, a risk limit
 *    quietly eating the best signals is indistinguishable from a strategy that
 *    produced none, and the backtest stops being evidence about anything.
 *
 * Deterministic and I/O-free: no clock, no RNG, no filesystem. Time and equity
 * are passed in, so a paper session and a backtest exercise identical code.
 */

import { equity as portfolioEquity, exposure, commissionFor, canOpen } from "./portfolio.js"

export const DEFAULT_RISK_CONFIG = {
  /** Fraction of equity risked per trade, entry -> stop. The whole point. */
  riskPerTradePct: 0.01,
  /** Single position cap as a fraction of equity — bounds a sizing mistake. */
  maxPositionPct: 0.25,
  maxPortfolioExposurePct: 0.9,
  maxConcentrationPct: 0.25,
  /** Kill switch: loss against the day's opening equity. */
  maxDailyLossPct: 0.03,
  /** Kill switch: peak-to-trough equity decline. */
  maxDrawdownPct: 0.2,
  maxOpenPositions: 5,
  /** A stop inside the noise is not a stop; it is a scheduled exit with a cost. */
  minStopDistancePct: 0.005,
  /** When false the limits still reject individual trades but never latch. */
  killSwitchEnabled: true,
}

/**
 * Every code assess() can return, with what it means. Exported so a UI can
 * explain a rejection without keeping its own copy of the vocabulary, which
 * would drift out of step with this file.
 */
export const RISK_CODES = [
  { code: "OK", kind: "approval", description: "Passed every risk check; the order may be sent." },
  { code: "KILL_SWITCH_TRIPPED", kind: "halt", description: "Trading is halted until the switch is reset. No new risk is taken." },
  { code: "MAX_DRAWDOWN", kind: "halt", description: "Peak-to-trough equity decline has reached the configured limit." },
  { code: "MAX_DAILY_LOSS", kind: "halt", description: "Loss against the day's opening equity has reached the daily limit." },
  { code: "NO_STOP", kind: "input", description: "No stop price was supplied, so risk per share is undefined and the position cannot be sized." },
  { code: "STOP_ABOVE_ENTRY", kind: "input", description: "The stop sits at or above the entry price, which is not a stop on a long." },
  { code: "STOP_TOO_TIGHT", kind: "input", description: "The stop is closer than minStopDistancePct; normal noise would fill it." },
  { code: "BAD_PRICE", kind: "input", description: "No usable entry price for this symbol." },
  { code: "ALREADY_OPEN", kind: "portfolio", description: "A position in this symbol is already open; adding would double the intended risk." },
  { code: "SIZE_ZERO", kind: "sizing", description: "The risk budget divided by the stop distance rounds to zero shares." },
  { code: "MAX_POSITIONS", kind: "portfolio", description: "The portfolio already holds the maximum number of simultaneous positions." },
  { code: "MAX_CONCENTRATION", kind: "portfolio", description: "A single position would exceed the per-position share of equity." },
  { code: "MAX_EXPOSURE", kind: "portfolio", description: "Total invested capital would exceed the portfolio exposure ceiling." },
  { code: "INSUFFICIENT_CASH", kind: "portfolio", description: "Not enough cash to buy even one share including commission." },
]

const CODE_INDEX = RISK_CODES.reduce((acc, c) => {
  acc[c.code] = c
  return acc
}, {})

export function describeCode(code) {
  return CODE_INDEX[code] ? CODE_INDEX[code].description : `Unknown risk code: ${code}`
}

/* --------------------------------------------------------------------------
   Engine construction and mutable state
   -------------------------------------------------------------------------- */

/**
 * The engine is the only stateful thing in this file. It holds the two running
 * baselines a kill switch needs — the equity peak and the day's opening equity —
 * because neither can be recovered from a single point-in-time snapshot.
 */
export function createRiskEngine(config = {}) {
  return {
    config: { ...DEFAULT_RISK_CONFIG, ...config },
    state: {
      peakEquity: null,
      dayStartEquity: null,
      drawdownPct: 0,
      dayPnlPct: 0,
      tripped: false,
      trippedReason: null,
      trippedCode: null,
      trippedAt: null,
      lastEquity: null,
      lastTime: null,
    },
    counters: { assessed: 0, approved: 0, rejected: 0 },
  }
}

/** Folds one equity observation into the baselines. Never latches by itself. */
function observeEquity(engine, eq, time) {
  const s = engine.state
  if (!Number.isFinite(eq)) return s

  if (s.peakEquity === null || eq > s.peakEquity) s.peakEquity = eq
  if (s.dayStartEquity === null) s.dayStartEquity = eq

  s.drawdownPct = s.peakEquity > 0 ? (s.peakEquity - eq) / s.peakEquity : 0
  s.dayPnlPct = s.dayStartEquity > 0 ? (eq - s.dayStartEquity) / s.dayStartEquity : 0
  s.lastEquity = eq
  if (time !== undefined) s.lastTime = time
  return s
}

/**
 * Public equity feed. Call it once per bar, or per mark, from the loop that owns
 * the portfolio; it maintains the drawdown and daily-loss baselines and latches
 * the kill switch the moment a limit is breached.
 */
export function updateEquity(engine, { equity, time } = {}) {
  const s = observeEquity(engine, equity, time)
  const cfg = engine.config
  if (!cfg.killSwitchEnabled || s.tripped) return s

  if (s.drawdownPct >= cfg.maxDrawdownPct) {
    tripKillSwitch(
      engine,
      `Drawdown ${(s.drawdownPct * 100).toFixed(2)}% reached the ${(cfg.maxDrawdownPct * 100).toFixed(0)}% limit`,
      { code: "MAX_DRAWDOWN", time }
    )
    return s
  }
  if (s.dayPnlPct <= -cfg.maxDailyLossPct) {
    tripKillSwitch(
      engine,
      `Day P&L ${(s.dayPnlPct * 100).toFixed(2)}% reached the ${(cfg.maxDailyLossPct * 100).toFixed(0)}% daily loss limit`,
      { code: "MAX_DAILY_LOSS", time }
    )
  }
  return s
}

/**
 * Starts a new session. Rebaselines the daily loss limit, and clears a trip that
 * was caused BY that limit — a daily loss limit is by definition spent at the
 * close. A drawdown trip is not: it survives the day boundary and needs an
 * explicit resetKillSwitch(), because the equity that caused it has not come
 * back just because the date changed.
 */
export function startDay(engine, { equity, time } = {}) {
  const s = engine.state
  if (Number.isFinite(equity)) observeEquity(engine, equity, time)
  s.dayStartEquity = Number.isFinite(equity) ? equity : s.lastEquity
  s.dayPnlPct = 0
  s.dayStartedAt = time ?? null
  if (s.tripped && s.trippedCode === "MAX_DAILY_LOSS") {
    s.tripped = false
    s.trippedReason = null
    s.trippedCode = null
    s.trippedAt = null
  }
  return s
}

export function tripKillSwitch(engine, reason, options = {}) {
  const s = engine.state
  s.tripped = true
  s.trippedReason = reason || "Kill switch tripped manually"
  s.trippedCode = options.code || "KILL_SWITCH_TRIPPED"
  s.trippedAt = options.time ?? s.lastTime ?? null
  return s
}

/**
 * Clears the switch. Rebaselines the equity peak to the last observed equity by
 * default, because clearing a drawdown trip without moving the peak would
 * re-trip on the very next assessment and look like the reset did nothing.
 * Pass { rebaseline: false } to keep the original peak.
 */
export function resetKillSwitch(engine, options = {}) {
  const s = engine.state
  const rebaseline = options.rebaseline !== false
  s.tripped = false
  s.trippedReason = null
  s.trippedCode = null
  s.trippedAt = null
  if (rebaseline && Number.isFinite(s.lastEquity)) {
    s.peakEquity = s.lastEquity
    s.drawdownPct = 0
    s.dayStartEquity = s.lastEquity
    s.dayPnlPct = 0
  }
  return s
}

/* --------------------------------------------------------------------------
   Assessment
   -------------------------------------------------------------------------- */

function record(checks, name, passed, detail) {
  checks.push({ name, passed, detail })
  return passed
}

function reject(engine, checks, code, reason, extra = {}) {
  engine.counters.assessed += 1
  engine.counters.rejected += 1
  return {
    approved: false,
    code,
    reason,
    shares: 0,
    riskAmount: null,
    stopDistancePct: extra.stopDistancePct ?? null,
    checks,
    ...extra,
  }
}

/**
 * Decide whether a signal may become a position, and at what size.
 *
 * @param {object} engine    from createRiskEngine()
 * @param {object} args
 * @param {object} args.portfolio   a portfolio.js portfolio — the final authority on admission
 * @param {string} args.symbol
 * @param {number} args.price       intended entry price (the NEXT bar's open in a backtest)
 * @param {number} args.stopPrice   where the trade is wrong. Required; sizing is undefined without it.
 * @param {object} [args.features]  feature vector from features.js, carried into the audit record
 * @param {*}      [args.time]      decision timestamp, passed in — never read from a clock
 * @param {number} [args.equityNow] equity override; defaults to the portfolio's own
 */
export function assess(engine, { portfolio, symbol, price, stopPrice, features, time, equityNow } = {}) {
  if (!engine || !engine.config) throw new TypeError("assess() needs a risk engine from createRiskEngine()")
  if (!portfolio || !portfolio.config) throw new TypeError("assess() needs a portfolio from createPortfolio()")

  const cfg = engine.config
  const checks = []
  const eq = Number.isFinite(equityNow) ? equityNow : portfolioEquity(portfolio)

  /* ---- 1. Account-level gates. These outrank any signal. ---- */

  observeEquity(engine, eq, time)
  const s = engine.state

  if (!record(checks, "kill_switch", !s.tripped, s.tripped ? s.trippedReason : "Kill switch is armed and clear")) {
    return reject(
      engine,
      checks,
      "KILL_SWITCH_TRIPPED",
      `Trading halted: ${s.trippedReason}. Reset the kill switch to resume.`
    )
  }

  const ddOk = s.drawdownPct < cfg.maxDrawdownPct
  record(
    checks,
    "max_drawdown",
    ddOk,
    `Drawdown ${(s.drawdownPct * 100).toFixed(2)}% of a ${(cfg.maxDrawdownPct * 100).toFixed(0)}% limit`
  )
  if (!ddOk) {
    const reason =
      `Drawdown ${(s.drawdownPct * 100).toFixed(2)}% has reached the ${(cfg.maxDrawdownPct * 100).toFixed(0)}% limit; ` +
      "no new risk until equity recovers or the switch is reset"
    if (cfg.killSwitchEnabled) tripKillSwitch(engine, reason, { code: "MAX_DRAWDOWN", time })
    return reject(engine, checks, "MAX_DRAWDOWN", reason)
  }

  const dayOk = s.dayPnlPct > -cfg.maxDailyLossPct
  record(
    checks,
    "max_daily_loss",
    dayOk,
    `Day P&L ${(s.dayPnlPct * 100).toFixed(2)}% against a ${(cfg.maxDailyLossPct * 100).toFixed(0)}% loss limit`
  )
  if (!dayOk) {
    const reason =
      `Day P&L ${(s.dayPnlPct * 100).toFixed(2)}% has reached the ${(cfg.maxDailyLossPct * 100).toFixed(0)}% daily loss limit; ` +
      "stopping for the session"
    if (cfg.killSwitchEnabled) tripKillSwitch(engine, reason, { code: "MAX_DAILY_LOSS", time })
    return reject(engine, checks, "MAX_DAILY_LOSS", reason)
  }

  /* ---- 2. Inputs. Bad inputs must never be sized around. ---- */

  const priceOk = Number.isFinite(price) && price > 0
  record(checks, "price_valid", priceOk, priceOk ? `Entry price $${price.toFixed(2)}` : "No usable entry price")
  if (!priceOk) return reject(engine, checks, "BAD_PRICE", `No usable entry price for ${symbol}`)

  const equityOk = Number.isFinite(eq) && eq > 0
  record(checks, "equity_positive", equityOk, equityOk ? `Equity $${eq.toFixed(2)}` : "Equity is zero or negative")
  if (!equityOk) {
    return reject(engine, checks, "INSUFFICIENT_CASH", "Account equity is zero or negative; there is nothing left to risk")
  }

  const alreadyOpen = portfolio.positions.has(symbol)
  record(
    checks,
    "not_already_open",
    !alreadyOpen,
    alreadyOpen ? `Already holding ${symbol}` : `No open position in ${symbol}`
  )
  if (alreadyOpen) {
    return reject(
      engine,
      checks,
      "ALREADY_OPEN",
      `Already holding ${symbol}; adding would double the intended risk on one thesis`
    )
  }

  const hasStop = Number.isFinite(stopPrice)
  record(checks, "stop_present", hasStop, hasStop ? `Stop $${stopPrice.toFixed(2)}` : "No stop price supplied")
  if (!hasStop) {
    return reject(
      engine,
      checks,
      "NO_STOP",
      `No stop for ${symbol}: risk per share is undefined, so the position cannot be sized`
    )
  }

  const stopBelow = stopPrice < price
  record(checks, "stop_below_entry", stopBelow, `Stop $${stopPrice.toFixed(2)} vs entry $${price.toFixed(2)}`)
  if (!stopBelow) {
    return reject(
      engine,
      checks,
      "STOP_ABOVE_ENTRY",
      `Stop $${stopPrice.toFixed(2)} is at or above the $${price.toFixed(2)} entry; that is a target, not a stop`
    )
  }

  const stopDistance = price - stopPrice
  const stopDistancePct = stopDistance / price
  const wideEnough = stopDistancePct >= cfg.minStopDistancePct
  record(
    checks,
    "stop_distance",
    wideEnough,
    `Stop is ${(stopDistancePct * 100).toFixed(2)}% away, minimum ${(cfg.minStopDistancePct * 100).toFixed(2)}%`
  )
  if (!wideEnough) {
    return reject(
      engine,
      checks,
      "STOP_TOO_TIGHT",
      `Stop is only ${(stopDistancePct * 100).toFixed(2)}% from entry, inside the ` +
        `${(cfg.minStopDistancePct * 100).toFixed(2)}% noise floor; normal intraday range would fill it`,
      { stopDistancePct }
    )
  }

  /* ---- 3. Sizing. Risk first, share count second. ---- */

  const riskBudget = eq * cfg.riskPerTradePct
  // THE LINE THAT MAKES THIS A RISK ENGINE: the wider the stop, the smaller the
  // position, so the dollar loss at the stop is constant across every trade.
  const riskShares = Math.floor(riskBudget / stopDistance)
  record(
    checks,
    "risk_budget",
    riskShares > 0,
    `$${riskBudget.toFixed(2)} at risk / $${stopDistance.toFixed(2)} per share = ${riskShares} shares`
  )
  if (riskShares <= 0) {
    return reject(
      engine,
      checks,
      "SIZE_ZERO",
      `A $${riskBudget.toFixed(2)} risk budget over a $${stopDistance.toFixed(2)} stop distance rounds to zero shares`,
      { stopDistancePct }
    )
  }

  // The position cap is the backstop against a sizing mistake: a very tight stop
  // would otherwise buy an enormous position for the same nominal risk, and one
  // bad gap through that stop would cost far more than the budgeted amount.
  const sizeCapPct = Math.min(cfg.maxPositionPct, cfg.maxConcentrationPct)
  const capShares = Math.floor((eq * sizeCapPct) / price)
  record(
    checks,
    "position_cap",
    capShares > 0,
    `Cap ${(sizeCapPct * 100).toFixed(0)}% of $${eq.toFixed(2)} equity = ${capShares} shares at $${price.toFixed(2)}`
  )
  if (capShares <= 0) {
    return reject(
      engine,
      checks,
      "MAX_CONCENTRATION",
      `One share of ${symbol} at $${price.toFixed(2)} is ${((price / eq) * 100).toFixed(1)}% of equity, ` +
        `past the ${(sizeCapPct * 100).toFixed(0)}% single-position cap`,
      { stopDistancePct }
    )
  }

  let shares = Math.min(riskShares, capShares)
  const cappedBySize = capShares < riskShares

  // Cash clamp. Commission depends on the share count, so the affordable size is
  // solved twice: once at the intended size, once at the reduced one.
  let affordable = Math.floor(Math.max(0, portfolio.cash - commissionFor(shares, portfolio.config)) / price)
  if (affordable < shares) {
    affordable = Math.floor(
      Math.max(0, portfolio.cash - commissionFor(Math.max(affordable, 1), portfolio.config)) / price
    )
  }
  record(
    checks,
    "cash_available",
    affordable > 0,
    `Cash $${portfolio.cash.toFixed(2)} affords ${affordable} shares at $${price.toFixed(2)} including commission`
  )
  if (affordable <= 0) {
    return reject(
      engine,
      checks,
      "INSUFFICIENT_CASH",
      `Cash $${portfolio.cash.toFixed(2)} does not cover one share of ${symbol} at $${price.toFixed(2)} plus commission`,
      { stopDistancePct }
    )
  }
  const cappedByCash = affordable < shares
  shares = Math.min(shares, affordable)

  const notional = shares * price
  const riskAmount = shares * stopDistance

  /* ---- 4. Portfolio gates, evaluated at the size we actually intend to send ---- */

  const positionLimit = Math.min(cfg.maxOpenPositions, portfolio.config.maxPositions)
  const roomForMore = portfolio.positions.size < positionLimit
  record(checks, "max_positions", roomForMore, `Holding ${portfolio.positions.size} of a maximum ${positionLimit}`)
  if (!roomForMore) {
    return reject(
      engine,
      checks,
      "MAX_POSITIONS",
      `Already holding ${portfolio.positions.size} positions, the configured maximum of ${positionLimit}`,
      { stopDistancePct, intended: { shares, riskAmount } }
    )
  }

  const concentrationPct = notional / eq
  const concentrationOk = concentrationPct <= cfg.maxConcentrationPct
  record(
    checks,
    "concentration",
    concentrationOk,
    `${symbol} would be ${(concentrationPct * 100).toFixed(2)}% of equity, limit ${(cfg.maxConcentrationPct * 100).toFixed(0)}%`
  )
  if (!concentrationOk) {
    return reject(
      engine,
      checks,
      "MAX_CONCENTRATION",
      `${symbol} would be ${(concentrationPct * 100).toFixed(2)}% of equity, past the ` +
        `${(cfg.maxConcentrationPct * 100).toFixed(0)}% single-position limit`,
      { stopDistancePct, intended: { shares, riskAmount } }
    )
  }

  const projectedExposure = (exposure(portfolio) + notional) / eq
  const exposureOk = projectedExposure <= cfg.maxPortfolioExposurePct
  record(
    checks,
    "portfolio_exposure",
    exposureOk,
    `Exposure would be ${(projectedExposure * 100).toFixed(2)}% of equity, limit ${(cfg.maxPortfolioExposurePct * 100).toFixed(0)}%`
  )
  if (!exposureOk) {
    return reject(
      engine,
      checks,
      "MAX_EXPOSURE",
      `Exposure would reach ${(projectedExposure * 100).toFixed(2)}% of equity, past the ` +
        `${(cfg.maxPortfolioExposurePct * 100).toFixed(0)}% ceiling`,
      { stopDistancePct, intended: { shares, riskAmount } }
    )
  }

  // The portfolio owns admission. Asking it LAST means the risk engine can never
  // approve something the book itself would refuse — the two cannot disagree,
  // and the caller only ever has to read one verdict.
  const admission = canOpen(portfolio, symbol, price, shares)
  record(checks, "portfolio_admission", admission.allowed, admission.reason)
  if (!admission.allowed) {
    return reject(engine, checks, admission.code, admission.reason, {
      stopDistancePct,
      intended: { shares, riskAmount },
    })
  }

  engine.counters.assessed += 1
  engine.counters.approved += 1

  const boundBy = cappedByCash ? "cash" : cappedBySize ? "position cap" : "risk budget"
  return {
    approved: true,
    code: "OK",
    reason:
      `${shares} shares of ${symbol} at $${price.toFixed(2)}: $${riskAmount.toFixed(2)} at risk to the ` +
      `$${stopPrice.toFixed(2)} stop (${((riskAmount / eq) * 100).toFixed(2)}% of equity, bound by ${boundBy})`,
    shares,
    riskAmount,
    stopDistancePct,
    checks,
    // Everything a reviewer needs to reconstruct the arithmetic without re-running it.
    riskBudget,
    stopDistance,
    notional,
    notionalPct: concentrationPct,
    projectedExposurePct: projectedExposure,
    equity: eq,
    boundBy,
  }
}

/* --------------------------------------------------------------------------
   Audit
   -------------------------------------------------------------------------- */

/**
 * Flattens a decision into a record for the `audit` collection.
 *
 * This module deliberately does NOT import store.js: store.js touches the
 * filesystem, and risk.js has to stay importable anywhere a sizing preview is
 * wanted. The caller writes it and assigns the idempotency key:
 *
 *   append("audit", { id: makeId("risk", rec.idParts), ...rec })
 */
export function recordDecision(engine, decision, extra = {}) {
  const s = engine.state
  const d = decision || {}
  const symbol = extra.symbol ?? d.symbol ?? null
  const time = extra.time ?? d.time ?? null

  return {
    stage: "risk",
    symbol,
    time,
    approved: d.approved === true,
    code: d.code || "UNKNOWN",
    reason: d.reason || describeCode(d.code),
    shares: Number.isFinite(d.shares) ? d.shares : 0,
    riskAmount: d.riskAmount ?? null,
    riskBudget: d.riskBudget ?? null,
    stopDistancePct: d.stopDistancePct ?? null,
    notional: d.notional ?? null,
    equity: d.equity ?? s.lastEquity ?? null,
    boundBy: d.boundBy ?? null,
    // Only the failures are kept inline; the passing checks are reconstructable
    // from the config plus these numbers, and the full list is bulky.
    failedChecks: (d.checks || []).filter(c => !c.passed).map(c => ({ name: c.name, detail: c.detail })),
    checksRun: (d.checks || []).length,
    riskState: {
      peakEquity: s.peakEquity,
      dayStartEquity: s.dayStartEquity,
      drawdownPct: s.drawdownPct,
      dayPnlPct: s.dayPnlPct,
      tripped: s.tripped,
      trippedReason: s.trippedReason,
      trippedAt: s.trippedAt,
    },
    config: { ...engine.config },
    strategyId: extra.strategyId ?? null,
    signalId: extra.signalId ?? null,
    features: extra.features ?? null,
    /** Feed to store.makeId(); deterministic, so a replayed run writes nothing new. */
    idParts: ["risk", symbol, String(time), d.code || "UNKNOWN", String(d.shares ?? 0), extra.strategyId ?? ""],
  }
}

/* --------------------------------------------------------------------------
   Self-check:  node src/engine/risk.js
   -------------------------------------------------------------------------- */

/*
 * Wrapped in an async IIFE rather than using top-level await.
 *
 * This block is a CLI self-check and never runs in a browser — but a top-level
 * await makes the whole MODULE async as far as a bundler is concerned, and
 * webpack warns that the output may not run. /strategies/ now imports this
 * file to re-run backtests client-side, so that warning became real output on
 * every build. The guard also stops assuming `process` exists.
 */
if (typeof process !== "undefined" && process.argv?.[1]?.endsWith("risk.js")) {
  ;(async () => {
    const { createPortfolio, openPosition } = await import("./portfolio.js")

    const show = (label, r) => {
      const flag = r.approved ? "APPROVED" : "REJECTED"
      const risk = r.riskAmount === null ? "n/a" : `$${r.riskAmount.toFixed(2)}`
      const failed = r.checks.filter(c => !c.passed)
      console.log(`\n${label}`)
      console.log(`  ${flag}  [${r.code}]  shares=${r.shares}  risk=${risk}`)
      console.log(`  ${r.reason}`)
      console.log(
        `  checks: ${r.checks.length} run, ${failed.length} failed` +
          (failed.length ? ` -> ${failed.map(c => c.name).join(", ")}` : "")
      )
    }

    console.log("=== MarketScan risk engine self-check ===")

    const portfolio = createPortfolio({ initialCash: 100000 })
    const engine = createRiskEngine()
    const t = "2026-09-09T13:31:00Z"
    startDay(engine, { equity: 100000, time: "2026-09-09T13:30:00Z" })
    console.log(
      `\nequity $${portfolioEquity(portfolio).toFixed(2)}  riskPerTrade ` +
        `${(engine.config.riskPerTradePct * 100).toFixed(1)}%  =>  ` +
        `$${(100000 * engine.config.riskPerTradePct).toFixed(2)} of risk per trade`
    )

    show("1. NVDA $100 entry, $95 stop (5% stop)", assess(engine, { portfolio, symbol: "NVDA", price: 100, stopPrice: 95, time: t }))
    show(
      "2. AMD $100 entry, $80 stop (20% stop) — a wider stop must buy FEWER shares for the same dollar risk",
      assess(engine, { portfolio, symbol: "AMD", price: 100, stopPrice: 80, time: t })
    )
    show("3. TSLA $100 entry, $99.90 stop (0.10% stop)", assess(engine, { portfolio, symbol: "TSLA", price: 100, stopPrice: 99.9, time: t }))
    show("4. MSFT $100 entry, $104 stop", assess(engine, { portfolio, symbol: "MSFT", price: 100, stopPrice: 104, time: t }))
    show("5. AAPL $100 entry, no stop", assess(engine, { portfolio, symbol: "AAPL", price: 100, stopPrice: null, time: t }))
    show(
      "6. META $50 entry, $49.50 stop (1% stop) — risk alone wants 2000 shares, the position cap must bind",
      assess(engine, { portfolio, symbol: "META", price: 50, stopPrice: 49.5, time: t })
    )
    show(
      "7. BRK $30,000 entry, $29,800 stop — one share is 30% of equity, past the single-position cap",
      assess(engine, { portfolio, symbol: "BRK", price: 30000, stopPrice: 29800, time: t })
    )
    show(
      "8. BRK.A $40,000 entry, $36,000 stop — one share risks $4,000 against a $1,000 budget",
      assess(engine, { portfolio, symbol: "BRK.A", price: 40000, stopPrice: 36000, time: t })
    )

    const full = createPortfolio({ initialCash: 100000 })
    const fullEngine = createRiskEngine({ maxOpenPositions: 2 })
    openPosition(full, { symbol: "AAA", shares: 10, price: 50, time: t, reason: "seed" })
    openPosition(full, { symbol: "BBB", shares: 10, price: 50, time: t, reason: "seed" })
    show("9. A third position with maxOpenPositions=2", assess(fullEngine, { portfolio: full, symbol: "CCC", price: 100, stopPrice: 95, time: t }))
    show("10. Re-entering a symbol already held", assess(fullEngine, { portfolio: full, symbol: "AAA", price: 50, stopPrice: 47, time: t }))

    const broke = createPortfolio({ initialCash: 100000 })
    broke.cash = 40
    show("11. $60 entry with $40 of cash left", assess(createRiskEngine(), { portfolio: broke, symbol: "F", price: 60, stopPrice: 57, time: t, equityNow: 100000 }))

    // Four positions at 22% of equity each leaves one slot but almost no room
    // under the exposure ceiling.
    const heavy = createPortfolio({ initialCash: 100000 })
    for (const sym of ["W", "X", "Y", "Z"]) {
      openPosition(heavy, { symbol: sym, shares: 220, price: 100, time: t, reason: "seed" })
    }
    show(
      `12. A fifth position with ${((exposure(heavy) / portfolioEquity(heavy)) * 100).toFixed(1)}% already invested`,
      assess(createRiskEngine(), { portfolio: heavy, symbol: "V", price: 100, stopPrice: 90, time: t })
    )

    const dayEngine = createRiskEngine()
    startDay(dayEngine, { equity: 100000, time: t })
    show(
      "13. Equity $96,500 after opening the day at $100,000 (-3.50%)",
      assess(dayEngine, { portfolio, symbol: "NVDA", price: 100, stopPrice: 95, time: t, equityNow: 96500 })
    )

    const ddEngine = createRiskEngine()
    updateEquity(ddEngine, { equity: 100000, time: t })
    startDay(ddEngine, { equity: 78000, time: t })
    show(
      "14. Equity $78,000 against a $100,000 peak (-22% drawdown)",
      assess(ddEngine, { portfolio, symbol: "NVDA", price: 100, stopPrice: 95, time: t, equityNow: 78000 })
    )
    console.log(
      `  state: tripped=${ddEngine.state.tripped} code=${ddEngine.state.trippedCode} ` +
        `drawdown=${(ddEngine.state.drawdownPct * 100).toFixed(2)}%`
    )
    show("15. The next signal while the switch is tripped", assess(ddEngine, { portfolio, symbol: "AMD", price: 100, stopPrice: 95, time: t, equityNow: 78000 }))
    resetKillSwitch(ddEngine)
    show("16. The same signal after resetKillSwitch()", assess(ddEngine, { portfolio, symbol: "AMD", price: 100, stopPrice: 95, time: t, equityNow: 78000 }))

    const audited = recordDecision(
      engine,
      assess(engine, { portfolio, symbol: "NVDA", price: 100, stopPrice: 95, time: t }),
      { symbol: "NVDA", time: t, strategyId: "breakout-20d" }
    )
    console.log("\n17. recordDecision() audit record")
    console.log(
      "  " +
        JSON.stringify({
          stage: audited.stage,
          symbol: audited.symbol,
          code: audited.code,
          shares: audited.shares,
          riskAmount: audited.riskAmount,
          checksRun: audited.checksRun,
          failed: audited.failedChecks.length,
          idParts: audited.idParts,
        })
    )

    console.log(`\ncounters: ${JSON.stringify(engine.counters)}`)
    console.log(`codes defined: ${RISK_CODES.length}`)
    console.log("\n=== self-check complete ===")
  })()
}
