/**
 * Performance analytics over a backtest result.
 *
 * Every figure here is computed from the realised trade list and the equity
 * curve — never estimated, never annualised from a sample too small to support
 * it. Where a statistic is not meaningful on the data given, it returns null
 * and says why in `caveats`, because a Sharpe ratio computed from nine trades
 * is worse than no Sharpe ratio at all: it looks authoritative and is noise.
 */

const TRADING_DAYS = 252

function sum(values) {
  let t = 0
  for (const v of values) t += v
  return t
}

function mean(values) {
  return values.length ? sum(values) / values.length : null
}

function stdev(values) {
  if (values.length < 2) return null
  const m = mean(values)
  let acc = 0
  for (const v of values) acc += (v - m) ** 2
  return Math.sqrt(acc / (values.length - 1))
}

/** Peak-to-trough decline on the equity curve, as a positive percentage. */
function maxDrawdown(curve) {
  if (!curve.length) return { pct: null, peak: null, trough: null }
  let peak = curve[0].equity
  let worst = 0
  let peakAt = curve[0].time
  let troughAt = curve[0].time
  let bestPeak = peak
  let bestTrough = peak

  for (const point of curve) {
    if (point.equity > peak) {
      peak = point.equity
      peakAt = point.time
    }
    const dd = peak > 0 ? (peak - point.equity) / peak : 0
    if (dd > worst) {
      worst = dd
      bestPeak = peak
      bestTrough = point.equity
      troughAt = point.time
    }
  }
  return {
    pct: worst * 100,
    peak: bestPeak,
    trough: bestTrough,
    peakAt,
    troughAt,
  }
}

/**
 * @param {object} result  from backtestSymbol or backtestPortfolio
 */
export function analyze(result) {
  const trades = result.trades || []
  const curve = result.equityCurve || []
  const caveats = []

  const wins = trades.filter(t => t.pnl > 0)
  const losses = trades.filter(t => t.pnl <= 0)

  const grossProfit = sum(wins.map(t => t.pnl))
  const grossLoss = Math.abs(sum(losses.map(t => t.pnl)))
  const netPnl = sum(trades.map(t => t.pnl))
  const fees = sum(trades.map(t => t.fees || 0))

  const startEquity = curve.length ? curve[0].equity : (result.config?.initialCash ?? null)
  const endEquity = curve.length ? curve[curve.length - 1].equity : startEquity
  const totalReturnPct =
    startEquity && startEquity > 0 ? ((endEquity - startEquity) / startEquity) * 100 : null

  const winRate = trades.length ? (wins.length / trades.length) * 100 : null
  const avgWin = mean(wins.map(t => t.pnl))
  const avgLoss = mean(losses.map(t => t.pnl))

  // Expectancy: the average dollar outcome of taking one more trade.
  const expectancy = trades.length ? netPnl / trades.length : null

  // Profit factor is undefined with no losing trades — Infinity is not a result.
  let profitFactor = null
  if (grossLoss > 0) profitFactor = grossProfit / grossLoss
  else if (grossProfit > 0) caveats.push("Profit factor undefined: no losing trades")

  /* ---- Sharpe, only where it means something ---- */
  let sharpe = null
  if (curve.length >= 30) {
    const rets = []
    for (let i = 1; i < curve.length; i += 1) {
      const prev = curve[i - 1].equity
      if (prev > 0) rets.push((curve[i].equity - prev) / prev)
    }
    const m = mean(rets)
    const sd = stdev(rets)
    if (sd && sd > 0) {
      // Zero risk-free rate, stated rather than assumed away.
      sharpe = (m / sd) * Math.sqrt(TRADING_DAYS)
    }
    if (rets.length < 60) {
      caveats.push(`Sharpe from only ${rets.length} periods — treat as indicative`)
    }
  } else {
    caveats.push("Sharpe not computed: fewer than 30 equity points")
  }

  if (trades.length > 0 && trades.length < 30) {
    caveats.push(`Only ${trades.length} trades — win rate and expectancy are high-variance`)
  }
  if (trades.length === 0) {
    caveats.push("No trades were taken; the entry condition never occurred on this data")
  }

  const dd = maxDrawdown(curve)

  /* ---- Exposure: share of bars actually holding a position ---- */
  let exposurePct = null
  if (curve.length) {
    const held = curve.filter(p => (p.exposure ?? 0) > 0).length
    exposurePct = (held / curve.length) * 100
  }

  const holdBars = trades.map(t => t.barsHeld).filter(Number.isFinite)

  return {
    strategy: result.strategy,
    params: result.params,

    trades: trades.length,
    wins: wins.length,
    losses: losses.length,
    winRate,
    lossRate: winRate === null ? null : 100 - winRate,

    netPnl,
    grossProfit,
    grossLoss,
    fees,
    totalReturnPct,
    startEquity,
    endEquity,

    avgWin,
    avgLoss,
    expectancy,
    profitFactor,
    payoffRatio: avgLoss && avgLoss !== 0 ? Math.abs(avgWin / avgLoss) : null,

    sharpe,
    maxDrawdownPct: dd.pct,
    drawdownPeak: dd.peak,
    drawdownTrough: dd.trough,

    exposurePct,
    avgBarsHeld: mean(holdBars),

    caveats,
  }
}

/** Side-by-side comparison, sorted by expectancy. */
export function compare(results) {
  return results
    .map(analyze)
    .sort((a, b) => (b.expectancy ?? -Infinity) - (a.expectancy ?? -Infinity))
}

/** A compact console table — used by the CLI and the tests. */
export function formatTable(analyses) {
  const head =
    "STRATEGY".padEnd(24) +
    "TRADES".padStart(7) +
    "WIN%".padStart(7) +
    "NET P&L".padStart(11) +
    "RETURN".padStart(9) +
    "EXPECT".padStart(9) +
    "PF".padStart(7) +
    "MAXDD".padStart(8) +
    "SHARPE".padStart(8)
  const rows = analyses.map(a =>
    String(a.strategy?.name || "—").slice(0, 23).padEnd(24) +
    String(a.trades).padStart(7) +
    (a.winRate === null ? "—" : a.winRate.toFixed(0) + "%").padStart(7) +
    ("$" + (a.netPnl ?? 0).toFixed(0)).padStart(11) +
    (a.totalReturnPct === null ? "—" : a.totalReturnPct.toFixed(2) + "%").padStart(9) +
    (a.expectancy === null ? "—" : "$" + a.expectancy.toFixed(0)).padStart(9) +
    (a.profitFactor === null ? "—" : a.profitFactor.toFixed(2)).padStart(7) +
    (a.maxDrawdownPct === null ? "—" : a.maxDrawdownPct.toFixed(1) + "%").padStart(8) +
    (a.sharpe === null ? "—" : a.sharpe.toFixed(2)).padStart(8)
  )
  return [head, ...rows].join("\n")
}
