/**
 * Multi-symbol portfolio backtest — ONE book, ONE pool of cash. (item 15, the real one)
 *
 * backtest.js::backtestPortfolio() runs every symbol in its own sandbox with its
 * own slice of capital. That models fourteen separate accounts which happen to
 * share a strategy, and it cannot express the one thing a portfolio actually
 * does: force signals to COMPETE. When four symbols break out on the same
 * morning and there is cash for two, a real book buys two of them. The sandboxed
 * version buys all four, out of money that does not exist, and reports a return
 * nobody could have earned. This module supersedes it. backtest.js is left
 * untouched: backtestSymbol() is still the right tool for one symbol.
 *
 * THE THREE PROPERTIES THAT MAKE THE OUTPUT EVIDENCE
 *
 * 1. NO LOOK-AHEAD. A decision taken from bar i fills at that symbol's NEXT
 *    bar's OPEN — never at bar i's close. Stops and targets are computed from
 *    bar i's features and checked against bar i+1's high/low, because a stop
 *    placed after bar i closed is genuinely live during bar i+1. A level is
 *    never checked against the very bar whose own high/low helped compute it.
 *
 * 2. CAPITAL CONTENTION IS EXPLICIT AND AUDITED. Candidates competing for the
 *    same bar are ranked by scoreSignal() and admitted in rank order until cash,
 *    the position count, the exposure ceiling or the concentration cap refuses
 *    the next one. Every refusal is recorded with a machine code AND a human
 *    sentence. A backtest that silently drops signals overstates nothing, but it
 *    hides why it traded what it traded, which is worse: it cannot be argued
 *    with. `rejections` is a first-class output here, not a diagnostic.
 *
 * 3. NOTHING IS LEFT OPEN. Every position is liquidated on the final timestamp,
 *    so the P&L is realised rather than flattered by an unrealised winner.
 *
 * SHARED CAPITAL IS THE WHOLE POINT. The portfolio, the sizing and the limits
 * are portfolio.js and risk.js — the same objects that will drive a paper
 * account — so a backtest result and a live session cannot disagree about what
 * "10% of equity" or "already holding five" means.
 *
 * Deterministic: no clock, no RNG, and the order counter is run-local rather
 * than module-global, so two runs over the same inputs produce byte-identical
 * JSON. The self-check at the bottom asserts exactly that.
 *
 * NODE ONLY, transitively: scoreSignal comes from signals.js, which imports the
 * filesystem-backed store. Never import this from src/pages/ or src/components/.
 */

import { prepare, featuresAt } from "./features.js"
import {
  DEFAULT_PORTFOLIO_CONFIG,
  createPortfolio,
  canOpen,
  openPosition,
  closePosition,
  sizePosition,
  mark,
  equity as portfolioEquity,
  exposure as portfolioExposure,
} from "./portfolio.js"
import { DEFAULT_RISK_CONFIG, createRiskEngine, assess, updateEquity, startDay } from "./risk.js"
/*
 * From scoring.js, not signals.js. Identical functions — signals.js re-exports
 * these — but signals.js also imports store.js for persistence, which needs
 * node:fs and node:crypto and so cannot be bundled for a browser. Importing
 * the arithmetic directly is what lets /strategies/ re-run this exact backtest
 * client-side against edited parameters.
 */
import { scoreSignal, WARMUP_BARS } from "./scoring.js"

export const DEFAULT_PORTFOLIO_BACKTEST_CONFIG = {
  ...DEFAULT_PORTFOLIO_CONFIG,
  /**
   * Bars of run-up before a symbol may trade. Evaluating a strategy at bar 3
   * does not produce "no signal", it produces a decision made on nulls — which
   * looks like no signal and quietly biases the sample. Counted PER SYMBOL, so
   * a symbol whose history starts late warms up late.
   */
  warmUpBars: WARMUP_BARS,
  /** Below this a symbol is excluded and said so, rather than half-tested. */
  minBarsPerSymbol: 30,
  /** Size through risk.js (risk-based sizing). false falls back to portfolio.js. */
  useRiskEngine: true,
  /**
   * When true a candidate with no stop price is refused (NO_STOP) rather than
   * sized by fixed fraction. Risk-based sizing is undefined without a stop, and
   * silently swapping sizing models mid-run would make the result unreadable.
   */
  requireStop: true,
  /** Liquidate everything on the final timestamp so P&L is realised. */
  closeAtEnd: true,
}

/**
 * Codes this module raises itself. Everything else in `rejections` comes from
 * risk.js (RISK_CODES) or portfolio.js unchanged, so one vocabulary covers the
 * backtester, the paper account and the UI.
 */
export const BACKTEST_CODES = [
  {
    code: "NO_FILL_BAR",
    kind: "execution",
    description:
      "The signal was queued but the symbol never printed another bar, so there was no open to fill at.",
  },
  {
    code: "NOT_ENOUGH_BARS",
    kind: "data",
    description:
      "The symbol's history is shorter than minBarsPerSymbol and it was excluded from the run.",
  },
]

/* --------------------------------------------------------------------------
   Timeline helpers
   -------------------------------------------------------------------------- */

/** Total order over timestamps, whether they are unix seconds or ISO strings. */
function compareTime(a, b) {
  if (typeof a === "number" && typeof b === "number") return a - b
  const x = String(a)
  const y = String(b)
  return x < y ? -1 : x > y ? 1 : 0
}

/**
 * Which calendar day a timestamp belongs to, for the daily-loss baseline.
 * Daily bars give one point per day; minute bars give many, and the risk
 * engine's day limit only means anything if the day boundary is real.
 */
function dayKeyOf(time) {
  if (typeof time === "number" && Number.isFinite(time)) {
    const seconds = time > 1e11 ? Math.floor(time / 1000) : time
    return Math.floor(seconds / 86400)
  }
  return String(time).slice(0, 10)
}

/**
 * One track per tradeable symbol: its bars, its precomputed indicator context
 * and a time -> index map. That map is what lets the loop walk a UNIFIED
 * timeline without ever assuming the arrays line up — a symbol that listed two
 * years into the window simply has no bar at the early timestamps.
 */
function buildTracks(symbols, barsBySymbol, cfg) {
  const tracks = []
  const excluded = []
  for (const symbol of symbols) {
    const bars = (barsBySymbol && barsBySymbol[symbol]) || []
    const count = Array.isArray(bars) ? bars.length : 0
    if (count < cfg.minBarsPerSymbol) {
      excluded.push({
        symbol,
        bars: count,
        code: "NOT_ENOUGH_BARS",
        reason: `${symbol} has ${count} bars, fewer than the ${cfg.minBarsPerSymbol} required to test`,
      })
      continue
    }
    const indexByTime = new Map()
    for (let i = 0; i < bars.length; i += 1) indexByTime.set(bars[i].time, i)
    tracks.push({ symbol, bars, ctx: prepare(bars), indexByTime })
  }
  return { tracks, excluded }
}

/** The sorted union of every symbol's bar timestamps. */
function buildTimeline(tracks) {
  const times = new Set()
  for (const track of tracks) for (const bar of track.bars) times.add(bar.time)
  return [...times].sort(compareTime)
}

function nullable(value) {
  return Number.isFinite(value) ? value : null
}

/* --------------------------------------------------------------------------
   The run
   -------------------------------------------------------------------------- */

/**
 * @param {object}   args
 * @param {string[]} args.symbols       order is the deterministic tie-break
 * @param {object}   args.barsBySymbol  { [symbol]: ascending OHLCV bars }
 * @param {object}   args.strategy      from strategy.js
 * @param {object}   [args.params]      overrides for strategy.params
 * @param {object}   [args.config]      overrides for DEFAULT_PORTFOLIO_BACKTEST_CONFIG
 * @param {object}   [args.riskConfig]  overrides for risk.js DEFAULT_RISK_CONFIG
 * @param {number}   [args.tradeFromIndex]
 *   First bar index at which an entry may be DECIDED. Bars before it are read —
 *   indicators warm up on them, positions are still marked and managed — but
 *   they can never open a position. This is what lets walk-forward prepend a
 *   run-up of TRAINING bars to a test slice without those bars producing trades
 *   that would then be counted as out-of-sample results. Defaults to 0, and is
 *   raised to warmUpBars in any case; it can only ever DELAY the first entry.
 */
export function runPortfolioBacktest({
  symbols, barsBySymbol, strategy, params, config, riskConfig, tradeFromIndex,
}) {
  if (!strategy || typeof strategy.entry !== "function") {
    throw new TypeError("runPortfolioBacktest() needs a strategy from strategy.js")
  }
  const symbolList = Array.isArray(symbols) ? [...symbols] : []
  const cfg = { ...DEFAULT_PORTFOLIO_BACKTEST_CONFIG, ...(config || {}) }
  const p = { ...strategy.params, ...(params || {}) }
  const rCfg = { ...DEFAULT_RISK_CONFIG, ...(riskConfig || {}) }
  const notes = []

  // The earliest index an entry may be decided at. warmUpBars covers indicator
  // run-up; tradeFromIndex covers a caller-supplied prefix that must not trade
  // (walk-forward's warm-up). Taking the max means neither can be weakened by
  // the other, and a caller can only ever push the first entry later.
  const entryFromIndex = Math.max(
    cfg.warmUpBars,
    Number.isFinite(tradeFromIndex) ? Math.max(0, Math.floor(tradeFromIndex)) : 0
  )

  const { tracks, excluded } = buildTracks(symbolList, barsBySymbol, cfg)
  for (const ex of excluded) notes.push(ex.reason)

  if (entryFromIndex > cfg.warmUpBars) {
    notes.push(
      `Bars 0-${entryFromIndex - 1} are read for indicator run-up only: no entry may be decided on them. ` +
        "Their outcomes belong to whatever window supplied them, not to this run."
    )
  }

  const timeline = buildTimeline(tracks)
  if (!tracks.length || !timeline.length) {
    return emptyResult(strategy, p, cfg, rCfg, symbolList, notes, excluded)
  }

  const portfolio = createPortfolio(cfg)
  const risk = cfg.useRiskEngine ? createRiskEngine(rCfg) : null

  const trades = []
  const orders = []
  const rejections = []
  const equityCurve = []
  const bySymbol = {}
  for (const track of tracks) {
    bySymbol[track.symbol] = {
      symbol: track.symbol,
      signals: 0,
      admitted: 0,
      rejected: 0,
      trades: 0,
      netPnl: 0,
    }
  }

  // Run-local, so the ids never depend on what ran earlier in this process.
  // A module-global counter (as backtest.js keeps) makes two identical runs
  // serialise differently, which would defeat the determinism check below.
  let orderSeq = 0
  const nextOrderId = prefix => {
    orderSeq += 1
    return `${prefix}-${orderSeq}`
  }

  // One ctx per symbol, reused: strategies read { params, symbol } only.
  const ctxBySymbol = new Map()
  const ctxFor = symbol => {
    if (!ctxBySymbol.has(symbol)) ctxBySymbol.set(symbol, { params: p, symbol })
    return ctxBySymbol.get(symbol)
  }

  /** symbol -> { reason, decidedAt }: the exit decided on that symbol's last bar. */
  const pendingExits = new Map()
  /** symbol -> { reason, features, score, decidedAt }: the entry awaiting an open. */
  const pendingEntries = new Map()

  const contention = { totalCandidates: 0, admitted: 0, rejected: 0, byCode: {} }
  const recordRejection = (time, symbol, code, reason, extra = {}) => {
    rejections.push({ time, symbol, code, reason, score: extra.score ?? null, ...extra })
    contention.rejected += 1
    contention.byCode[code] = (contention.byCode[code] || 0) + 1
    if (bySymbol[symbol]) bySymbol[symbol].rejected += 1
  }
  const sellFee = trade => trade.fees - (trade.entryFee || 0)

  let barsTested = 0
  let currentDay = null
  const lastIndex = timeline.length - 1

  for (let t = 0; t <= lastIndex; t += 1) {
    const time = timeline[t]
    const isFinal = t === lastIndex

    /* ---- Who printed a bar at this timestamp? Symbols that did not are simply
           absent: their marks, positions and pending orders all persist. ---- */
    const active = []
    for (const track of tracks) {
      const i = track.indexByTime.get(time)
      if (i === undefined) continue
      active.push({ track, i, bar: track.bars[i], features: featuresAt(track.ctx, i) })
      if (i >= entryFromIndex) barsTested += 1
    }
    if (!active.length) continue

    /* ======================================================================
       a. EXITS QUEUED ON THE PREVIOUS BAR, FILLED AT THIS BAR'S OPEN.
          Exits run before entries across the WHOLE book, because the cash a
          sale releases is cash the morning's buyers are entitled to compete
          for. Doing it per symbol in symbol order would hand an advantage to
          whichever ticker happened to sort first.
       ====================================================================== */
    for (const a of active) {
      const symbol = a.track.symbol
      const queued = pendingExits.get(symbol)
      if (!queued) continue
      pendingExits.delete(symbol)
      if (!portfolio.positions.has(symbol)) continue

      const fillPrice = a.bar.open * (1 - cfg.slippagePct)
      const done = closePosition(portfolio, { symbol, price: fillPrice, time, reason: queued.reason })
      if (!done.ok) continue
      trades.push(done.trade)
      orders.push({
        id: nextOrderId("exit"),
        symbol,
        side: "sell",
        shares: done.trade.shares,
        price: fillPrice,
        time,
        decidedAt: queued.decidedAt,
        status: "filled",
        reason: queued.reason,
        fee: sellFee(done.trade),
      })
    }

    /* ---- b(i). Mark every active symbol to its OPEN: the freshest price
           anyone could know at the moment the morning's orders are sent.
           Symbols that did not trade keep their last close. ---- */
    for (const a of active) mark(portfolio, a.track.symbol, a.bar.open)

    const equityAtOpen = portfolioEquity(portfolio)
    if (risk) {
      const dk = dayKeyOf(time)
      if (dk !== currentDay) {
        // Rebaselines the daily-loss limit and clears a trip caused by it.
        startDay(risk, { equity: equityAtOpen, time })
        currentDay = dk
      } else {
        updateEquity(risk, { equity: equityAtOpen, time })
      }
    }

    /* ======================================================================
       c. CAPITAL CONTENTION. Everything queued on a previous bar that now has
          an open to fill against competes for one pool of cash, strongest
          signal first. Nothing is dropped: whatever the book refuses is
          recorded with the code and the sentence that refused it.
       ====================================================================== */
    const candidates = []
    for (const a of active) {
      const symbol = a.track.symbol
      const queued = pendingEntries.get(symbol)
      if (!queued) continue
      pendingEntries.delete(symbol)
      if (portfolio.positions.has(symbol)) continue
      candidates.push({ a, queued })
    }

    if (candidates.length) {
      // Rank by signal score, descending. Ties break on symbol so the order is
      // total and two runs admit the same names in the same sequence.
      candidates.sort((x, y) => {
        const sx = Number.isFinite(x.queued.score) ? x.queued.score : -Infinity
        const sy = Number.isFinite(y.queued.score) ? y.queued.score : -Infinity
        if (sy !== sx) return sy - sx
        return compareTime(x.a.track.symbol, y.a.track.symbol)
      })
      contention.totalCandidates += candidates.length

      for (const { a, queued } of candidates) {
        const symbol = a.track.symbol
        const fillPrice = a.bar.open * (1 + cfg.slippagePct)
        const ctx = ctxFor(symbol)

        // The stop comes from the DECISION bar's features — yesterday's ATR is
        // what a trader placing this order at the open actually knows — priced
        // off the fill we are about to take.
        const provisional = { symbol, shares: 0, entryPrice: fillPrice, entryTime: time, barsHeld: 0 }
        const stop = strategy.stopPrice ? nullable(strategy.stopPrice(queued.features, provisional, ctx)) : null
        const target = strategy.targetPrice
          ? nullable(strategy.targetPrice(queued.features, provisional, ctx))
          : null

        const useRisk = Boolean(risk) && (cfg.requireStop || stop !== null)
        let verdict
        let shares = 0

        if (useRisk) {
          verdict = assess(risk, {
            portfolio,
            symbol,
            price: fillPrice,
            stopPrice: stop,
            features: queued.features,
            time,
          })
          shares = verdict.approved ? verdict.shares : 0
        } else {
          // Degraded path: fixed-fraction sizing with the portfolio as the only
          // gate. Used when the risk engine is switched off, or when a strategy
          // supplies no stop and requireStop was explicitly turned off.
          shares = sizePosition(portfolio, fillPrice)
          const admission = canOpen(portfolio, symbol, fillPrice, shares)
          verdict = {
            approved: admission.allowed,
            code: admission.code,
            reason: admission.reason,
            shares,
            riskAmount: stop !== null ? shares * (fillPrice - stop) : null,
          }
        }

        if (!verdict.approved) {
          recordRejection(time, symbol, verdict.code, verdict.reason, {
            score: queued.score,
            decidedAt: queued.decidedAt,
            price: fillPrice,
            intendedShares: verdict.shares || 0,
            sizedBy: useRisk ? "risk" : "portfolio",
            cashAtDecision: portfolio.cash,
            openPositions: portfolio.positions.size,
          })
          continue
        }

        const opened = openPosition(portfolio, {
          symbol,
          shares,
          price: fillPrice,
          time,
          reason: queued.reason,
          meta: { features: queued.features, score: queued.score, decidedAt: queued.decidedAt },
        })
        if (!opened.ok) {
          // Cash moved between the assessment and the fill. Recorded, never swallowed.
          recordRejection(time, symbol, opened.code || "INSUFFICIENT_CASH", opened.reason, {
            score: queued.score,
            decidedAt: queued.decidedAt,
            price: fillPrice,
            intendedShares: shares,
            sizedBy: useRisk ? "risk" : "portfolio",
          })
          continue
        }

        const position = opened.position
        position.entryIndex = a.i
        position.stop = stop
        position.target = target
        position.score = queued.score

        contention.admitted += 1
        if (bySymbol[symbol]) bySymbol[symbol].admitted += 1
        orders.push({
          id: nextOrderId("entry"),
          symbol,
          side: "buy",
          shares,
          price: fillPrice,
          time,
          decidedAt: queued.decidedAt,
          status: "filled",
          reason: queued.reason,
          fee: position.entryFee,
          score: queued.score,
          stop,
          target,
          riskAmount: verdict.riskAmount ?? null,
          sizedBy: useRisk ? "risk" : "portfolio",
        })
      }
    }

    /* ======================================================================
       d. STOPS AND TARGETS, INTRABAR. The levels were set from data that
          closed BEFORE this bar — or at this bar's open, for a position just
          entered — so checking them against this bar's high and low is
          execution, not foresight. Stop first when a bar spans both: we cannot
          know which came first inside the bar, and assuming the target is the
          assumption that pays.
       ====================================================================== */
    for (const a of active) {
      const symbol = a.track.symbol
      const position = portfolio.positions.get(symbol)
      if (!position) continue

      let exitPrice = null
      let exitReason = null
      if (position.stop !== null && a.bar.low <= position.stop) {
        // A gap through the stop fills at the open, not at the untouched level.
        exitPrice = Math.min(position.stop, a.bar.open) * (1 - cfg.slippagePct)
        exitReason = "Stop hit"
      } else if (position.target !== null && a.bar.high >= position.target) {
        exitPrice = Math.max(position.target, a.bar.open) * (1 - cfg.slippagePct)
        exitReason = "Target hit"
      }
      if (exitPrice === null) continue

      const done = closePosition(portfolio, { symbol, price: exitPrice, time, reason: exitReason })
      if (done.ok) {
        trades.push(done.trade)
        orders.push({
          id: nextOrderId("exit"),
          symbol,
          side: "sell",
          shares: done.trade.shares,
          price: exitPrice,
          time,
          decidedAt: time,
          status: "filled",
          reason: exitReason,
          fee: sellFee(done.trade),
        })
      }
      pendingExits.delete(symbol)
    }

    /* ---- b(ii). Mark to this bar's close: the book's end-of-bar value. ---- */
    for (const a of active) {
      mark(portfolio, a.track.symbol, a.bar.close)
      const position = portfolio.positions.get(a.track.symbol)
      if (position && Number.isFinite(position.entryIndex)) position.barsHeld = a.i - position.entryIndex
    }

    /* ======================================================================
       e. DECIDE WHAT HAPPENS NEXT BAR, from features known now. Exits first:
          a symbol that is leaving should not also be asked whether to enter.
       ====================================================================== */
    if (!isFinal) {
      for (const a of active) {
        const symbol = a.track.symbol
        const ctx = ctxFor(symbol)
        const f = a.features
        const position = portfolio.positions.get(symbol)

        if (position) {
          // Refresh the levels for the NEXT bar from what has just closed. The
          // strategy owns the level; this loop never tightens or loosens it.
          position.stop = strategy.stopPrice ? nullable(strategy.stopPrice(f, position, ctx)) : null
          position.target = strategy.targetPrice ? nullable(strategy.targetPrice(f, position, ctx)) : null

          if (!pendingExits.has(symbol)) {
            const wantExit = strategy.exit ? strategy.exit(f, position, ctx) : false
            if (wantExit) {
              pendingExits.set(symbol, { reason: wantExit.reason || "Exit rule", decidedAt: time })
            }
          }
          continue
        }

        if (a.i < entryFromIndex || pendingEntries.has(symbol)) continue
        const wantEntry = strategy.entry(f, ctx)
        if (!wantEntry) continue

        const scored = scoreSignal(f, "long")
        pendingEntries.set(symbol, {
          reason: wantEntry.reason || "Entry rule",
          features: f,
          score: scored.score,
          coverage: scored.coverage,
          decidedAt: time,
        })
        if (bySymbol[symbol]) bySymbol[symbol].signals += 1
      }
    }

    /* ======================================================================
       f. FINAL TIMESTAMP: liquidate. An open winner is not a result.
       ====================================================================== */
    if (isFinal && cfg.closeAtEnd) {
      const openSymbols = [...portfolio.positions.keys()].sort()
      for (const symbol of openSymbols) {
        const position = portfolio.positions.get(symbol)
        const lastMark = portfolio.marks.get(symbol)
        const price = (Number.isFinite(lastMark) ? lastMark : position.entryPrice) * (1 - cfg.slippagePct)
        const done = closePosition(portfolio, { symbol, price, time, reason: "Backtest ended" })
        if (!done.ok) continue
        trades.push(done.trade)
        orders.push({
          id: nextOrderId("exit"),
          symbol,
          side: "sell",
          shares: done.trade.shares,
          price,
          time,
          decidedAt: time,
          status: "filled",
          reason: "Backtest ended",
          fee: sellFee(done.trade),
        })
      }
      pendingExits.clear()
    }

    /* ---- g. One equity point per TIMELINE point, not per symbol bar, so the
           curve belongs to the book and metrics.analyze() reads it unchanged. ---- */
    const eq = portfolioEquity(portfolio)
    equityCurve.push({
      time,
      equity: eq,
      cash: portfolio.cash,
      exposure: portfolioExposure(portfolio),
      positions: portfolio.positions.size,
    })
    if (risk) updateEquity(risk, { equity: eq, time })
  }

  /* ---- Signals that never reached a fillable bar. Recorded, not dropped. ---- */
  const stranded = [...pendingEntries.keys()].sort()
  for (const symbol of stranded) {
    const queued = pendingEntries.get(symbol)
    contention.totalCandidates += 1
    recordRejection(
      timeline[lastIndex],
      symbol,
      "NO_FILL_BAR",
      `${symbol} signalled on its last bar, so there was never a following open to fill at`,
      { score: queued.score, decidedAt: queued.decidedAt }
    )
  }
  pendingEntries.clear()

  for (const trade of trades) {
    const row = bySymbol[trade.symbol]
    if (!row) continue
    row.trades += 1
    row.netPnl += trade.pnl
  }

  if (risk && risk.state.tripped) {
    notes.push(
      `Risk kill switch latched at ${String(risk.state.trippedAt)}: ${risk.state.trippedReason}. ` +
        "Every later candidate was refused — that is a limit doing its job, not an absence of signals."
    )
  }
  if (timeline.length > 1 && dayKeyOf(timeline[0]) !== dayKeyOf(timeline[1])) {
    notes.push(
      "Daily bars: an intraday daily-loss limit can only be observed once per bar, so it gates " +
        "entries at the open rather than halting mid-session."
    )
  }

  return {
    strategy: { id: strategy.id, name: strategy.name },
    params: p,
    config: cfg,
    riskConfig: rCfg,
    symbols: symbolList,
    tradedSymbols: tracks.map(track => track.symbol),
    excludedSymbols: excluded,

    trades,
    orders,
    rejections,
    equityCurve,

    finalEquity: portfolioEquity(portfolio),
    finalCash: portfolio.cash,
    realizedPnl: portfolio.realizedPnl,
    totalFees: portfolio.totalFees,
    barsTested,
    entryFromIndex,
    timeline: { from: timeline[0], to: timeline[lastIndex], points: timeline.length },

    contention,
    bySymbol,
    risk: risk
      ? {
          enabled: true,
          tripped: risk.state.tripped,
          trippedCode: risk.state.trippedCode,
          trippedReason: risk.state.trippedReason,
          trippedAt: risk.state.trippedAt,
          peakEquity: risk.state.peakEquity,
          counters: { ...risk.counters },
        }
      : { enabled: false },
    notes,
  }
}

function emptyResult(strategy, params, config, riskConfig, symbols, notes, excluded) {
  notes.push("No symbol had enough history to test; nothing was run.")
  return {
    strategy: { id: strategy.id, name: strategy.name },
    params,
    config,
    riskConfig,
    symbols,
    tradedSymbols: [],
    excludedSymbols: excluded,
    trades: [],
    orders: [],
    rejections: [],
    equityCurve: [],
    finalEquity: config.initialCash,
    finalCash: config.initialCash,
    realizedPnl: 0,
    totalFees: 0,
    barsTested: 0,
    timeline: { from: null, to: null, points: 0 },
    contention: { totalCandidates: 0, admitted: 0, rejected: 0, byCode: {} },
    bySymbol: {},
    risk: { enabled: false },
    notes,
  }
}

/**
 * A line per refusal code, with a real example of each.
 * Exported so the CLI and any UI read the same wording.
 */
export function formatContention(result) {
  const c = result.contention
  const admitPct = c.totalCandidates ? ((c.admitted / c.totalCandidates) * 100).toFixed(1) + "%" : "—"
  const lines = [
    `Candidates ${c.totalCandidates}   admitted ${c.admitted} (${admitPct})   refused ${c.rejected}`,
  ]
  const codes = Object.keys(c.byCode).sort(
    (a, b) => c.byCode[b] - c.byCode[a] || compareTime(a, b)
  )
  for (const code of codes) {
    const example = result.rejections.find(r => r.code === code)
    lines.push(
      `  ${String(code).padEnd(20)}${String(c.byCode[code]).padStart(5)}   e.g. ${example ? example.reason : ""}`
    )
  }
  return lines.join("\n")
}

/* --------------------------------------------------------------------------
   Self-check:  node --no-warnings src/engine/portfolioBacktest.js
   -------------------------------------------------------------------------- */

/*
 * Wrapped in an async IIFE rather than using top-level await.
 *
 * This block is a CLI self-check and never runs in a browser — but a top-level
 * await makes the whole MODULE async as far as a bundler is concerned, and
 * webpack warns that the output may not run. /strategies/ now imports this
 * file to re-run backtests client-side, so that warning became real output on
 * every build. The guard also stops assuming `process` exists.
 */
if (typeof process !== "undefined" && process.argv?.[1]?.endsWith("portfolioBacktest.js")) {
  ;(async () => {
    const { SYMBOLS } = await import("../data/companies.js")
    const { generateCandles } = await import("../data/candles.js")
    const { breakoutStrategy } = await import("./strategy.js")
    const { analyze, formatTable } = await import("./metrics.js")
    const { backtestPortfolio, resetOrderIds } = await import("./backtest.js")

    const TF = "5Y"
    const barsBySymbol = {}
    for (const symbol of SYMBOLS) barsBySymbol[symbol] = generateCandles(symbol, TF)

    const run = () =>
      runPortfolioBacktest({
        symbols: SYMBOLS,
        barsBySymbol,
        strategy: breakoutStrategy,
        config: { initialCash: 100000 },
      })

    const iso = t => new Date(t * 1000).toISOString().slice(0, 10)
    const result = run()

    console.log(`\n=== PORTFOLIO BACKTEST — ${breakoutStrategy.name}, ${SYMBOLS.length} symbols, ${TF} ===`)
    const lengths = [...new Set(SYMBOLS.map(s => barsBySymbol[s].length))].sort((a, b) => a - b)
    console.log(
      `Bars per symbol ${lengths.join("/")}   unified timeline ${result.timeline.points} points ` +
        `(${iso(result.timeline.from)} -> ${iso(result.timeline.to)})   ${result.barsTested} symbol-bars tested`
    )

    console.log("\n--- METRICS (one shared book) ---")
    const a = analyze(result)
    console.log(formatTable([a]))
    console.log(
      `\nFinal equity $${result.finalEquity.toFixed(2)}   realised P&L $${result.realizedPnl.toFixed(2)}   ` +
        `fees $${result.totalFees.toFixed(2)}   exposure ${a.exposurePct === null ? "—" : a.exposurePct.toFixed(1) + "%"}`
    )
    for (const c of a.caveats) console.log(`  caveat: ${c}`)

    console.log("\n--- CAPITAL CONTENTION ---")
    console.log(formatContention(result))

    const CONTENDED = ["INSUFFICIENT_CASH", "MAX_POSITIONS", "MAX_EXPOSURE", "MAX_CONCENTRATION", "SIZE_ZERO"]
    const contested = result.rejections.filter(r => CONTENDED.includes(r.code))
    console.log(`\nRefusals that were genuine capital contention: ${contested.length}`)
    for (const r of contested.slice(0, 5)) {
      console.log(`  ${iso(r.time)} ${String(r.symbol).padEnd(5)} score ${String(r.score).padStart(5)}  ${r.code}: ${r.reason}`)
    }

    console.log("\n--- PER SYMBOL ---")
    for (const s of result.tradedSymbols) {
      const row = result.bySymbol[s]
      console.log(
        `  ${s.padEnd(6)}signals ${String(row.signals).padStart(3)}   admitted ${String(row.admitted).padStart(3)}` +
          `   refused ${String(row.rejected).padStart(3)}   trades ${String(row.trades).padStart(3)}` +
          `   P&L $${row.netPnl.toFixed(0).padStart(8)}`
      )
    }
    for (const n of result.notes) console.log(`  note: ${n}`)

    /* ---- What the sandboxed version claims, for contrast ---- */
    resetOrderIds()
    const sandboxed = backtestPortfolio({
      symbols: SYMBOLS,
      barsBySymbol,
      strategy: breakoutStrategy,
      config: { initialCash: 100000 },
    })
    console.log(
      `\nSandboxed backtestPortfolio(): ${sandboxed.trades.length} trades — every symbol funded from its own ` +
        `slice of cash, so no signal ever competes. Shared capital took ${result.trades.length} and ` +
        `refused ${result.contention.rejected}.`
    )

    /* ---- Determinism ---- */
    const again = run()
    const identical = JSON.stringify(result) === JSON.stringify(again)
    console.log(`\nDeterminism: two runs produce ${identical ? "byte-identical" : "DIFFERENT"} JSON — ${identical ? "PASS" : "FAIL"}`)
    if (!identical) process.exitCode = 1

    /* ---- No look-ahead: no entry may fill on or before its own signal bar ---- */
    const earlyEntries = result.orders.filter(o => o.side === "buy" && compareTime(o.time, o.decidedAt) <= 0)
    const earlyExits = result.orders.filter(o => o.side === "sell" && compareTime(o.time, o.decidedAt) < 0)
    console.log(
      `No look-ahead: ${earlyEntries.length} entries filled on or before their signal bar, ` +
        `${earlyExits.length} fills before their decision — ${earlyEntries.length === 0 && earlyExits.length === 0 ? "PASS" : "FAIL"}`
    )
    if (earlyEntries.length || earlyExits.length) process.exitCode = 1

    /* ---- Shared capital: exposure must never exceed the ceiling ---- */
    const overExposed = result.equityCurve.filter(
      pt => pt.equity > 0 && pt.exposure / pt.equity > result.config.maxExposurePct + 1e-9
    )
    const overCash = result.equityCurve.filter(pt => pt.cash < -1e-9)
    console.log(
      `Shared capital: ${overExposed.length} points over the ${(result.config.maxExposurePct * 100).toFixed(0)}% ` +
        `exposure ceiling, ${overCash.length} points with negative cash — ` +
        `${overExposed.length === 0 && overCash.length === 0 ? "PASS" : "FAIL"}`
    )
    if (overExposed.length || overCash.length) process.exitCode = 1
  })()
}
