import React, { useEffect, useState, useCallback } from "react"

/**
 * The familiar black toast.
 *
 * Two decisions worth stating:
 *
 *  1. IT AUTO-DISMISSES, BUT NOT WHILE HOVERED. A message that vanishes while
 *     someone is still reading it is a message that was not delivered, and a
 *     lock explanation is exactly the kind of thing people re-read.
 *  2. RE-TRIGGERING THE SAME MESSAGE RESTARTS THE TIMER rather than stacking a
 *     second toast. Clicking four locked tabs in a row should leave one toast
 *     on screen, not four.
 *
 * The timer lives in an effect keyed on the message and a nonce, so nothing
 * touches `window` during the server render Gatsby performs at build time.
 */

const DEFAULT_MS = 4000

export function useToast() {
  const [toast, setToast] = useState(null)

  const show = useCallback(message => {
    if (!message) return
    // The nonce is what makes an identical repeat message restart the timer —
    // without it React sees the same state and the effect never re-runs.
    setToast({ message, nonce: Date.now() })
  }, [])

  const dismiss = useCallback(() => setToast(null), [])

  return { toast, show, dismiss }
}

export default function Toast({ toast, onDismiss, duration = DEFAULT_MS }) {
  const [paused, setPaused] = useState(false)

  useEffect(() => {
    if (!toast || paused) return undefined
    const id = setTimeout(onDismiss, duration)
    return () => clearTimeout(id)
  }, [toast, paused, duration, onDismiss])

  // Escape dismisses, like every other transient layer on the page.
  useEffect(() => {
    if (!toast) return undefined
    function onKeyDown(event) {
      if (event.key === "Escape") onDismiss()
    }
    document.addEventListener("keydown", onKeyDown)
    return () => document.removeEventListener("keydown", onKeyDown)
  }, [toast, onDismiss])

  if (!toast) return null

  return (
    <div
      className="toast"
      role="status"
      aria-live="polite"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <svg className="toast__icon" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
        <path
          d="M17 9V7a5 5 0 0 0-10 0v2H6a1 1 0 0 0-1 1v9a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-9a1 1 0 0 0-1-1h-1ZM9 7a3 3 0 0 1 6 0v2H9V7Z"
          fill="currentColor"
        />
      </svg>
      <span className="toast__text">{toast.message}</span>
      <button type="button" className="toast__close" onClick={onDismiss} aria-label="Dismiss">
        ×
      </button>
    </div>
  )
}
