/**
 * Strategy framework.
 *
 * A strategy is a plain object with pure predicate functions. It never touches
 * market data directly, never places orders and never knows about the broker —
 * it is handed a feature vector and answers "would I enter here?". That
 * separation is what lets the SAME strategy object drive the scanner, the
 * backtester and live paper execution without a line of duplicated logic.
 *
 * THESE ARE SAMPLE STRATEGIES, NOT A PROPRIETARY EDGE. They exist to exercise
 * and validate the framework end to end. Nate's actual rules have not been
 * supplied, so nothing here should be read as a recommendation — each is a
 * textbook formulation with its parameters exposed for the optimizer.
 *
 * CONTRACT
 *   id, name, description
 *   params            default parameter object; the optimizer sweeps these
 *   entry(f, ctx)     -> boolean | { reason }   may read only the current features
 *   exit(f, pos, ctx) -> boolean | { reason }
 *   stopPrice(f, pos, ctx)   -> number | null
 *   targetPrice(f, pos, ctx) -> number | null
 *   size(f, ctx)      -> fraction of equity to risk, or null for the default
 *
 * `f` is a feature vector from features.js, computed with no look-ahead.
 * `ctx` carries { params, symbol, bar }.
 */

/** A strategy may veto a trade for liquidity reasons regardless of its signal. */
function liquidEnough(f, params) {
  if (params.minDollarVolume && (f.dollarVolume === null || f.dollarVolume < params.minDollarVolume)) {
    return false
  }
  if (params.minPrice && f.close < params.minPrice) return false
  return true
}

/* ==========================================================================
   Sample strategy 1 — 20-day breakout with volume confirmation
   ========================================================================== */

export const breakoutStrategy = {
  id: "breakout-20d",
  name: "20-day breakout",
  description:
    "Enters when price closes above the prior 20-day high on above-average volume " +
    "and an intact uptrend. Exits on a close below the 10-day low or the ATR stop. " +
    "Sample strategy — a textbook Donchian breakout, not a proprietary rule set.",

  params: {
    rvolMin: 1.2,
    trendScoreMin: 1,
    atrStopMultiple: 2.5,
    targetMultiple: 5,
    minDollarVolume: 5e6,
    minPrice: 3,
    exitOnTrendLoss: true,
  },

  entry(f, ctx) {
    const p = ctx.params
    if (!liquidEnough(f, p)) return false
    if (f.breakoutAbove20 !== true) return false
    if (f.rvol === null || f.rvol < p.rvolMin) return false
    if (f.trendScore === null || f.trendScore < p.trendScoreMin) return false
    return {
      reason: `Closed ${f.breakoutMargin.toFixed(2)}% above the prior 20-day high ` +
        `on ${f.rvol.toFixed(2)}x volume`,
    }
  },

  exit(f, position, ctx) {
    const p = ctx.params
    // The trend has broken down: EMA stack no longer supports the position.
    if (p.exitOnTrendLoss && f.trendScore !== null && f.trendScore <= -1) {
      return { reason: "Trend score turned negative" }
    }
    if (f.breakdownBelow20 === true) {
      return { reason: "Closed below the prior 20-day low" }
    }
    return false
  },

  stopPrice(f, position, ctx) {
    if (f.atr14 === null) return null
    // Trails from the entry price, never above it, so a stop cannot loosen.
    return position.entryPrice - f.atr14 * ctx.params.atrStopMultiple
  },

  targetPrice(f, position, ctx) {
    if (f.atr14 === null) return null
    return position.entryPrice + f.atr14 * ctx.params.targetMultiple
  },
}

/* ==========================================================================
   Sample strategy 2 — mean reversion into an uptrend
   ========================================================================== */

export const meanReversionStrategy = {
  id: "meanrev-rsi",
  name: "RSI pullback in an uptrend",
  description:
    "Buys oversold RSI while price is still above its 50-day EMA, on the premise " +
    "that a pullback inside an uptrend resolves upward. Exits when RSI recovers. " +
    "Sample strategy — a standard RSI-2 style formulation.",

  params: {
    rsiEntry: 32,
    rsiExit: 60,
    requireAboveEma50: true,
    atrStopMultiple: 2,
    targetMultiple: 3,
    minDollarVolume: 5e6,
    minPrice: 3,
    maxHoldBars: 15,
  },

  entry(f, ctx) {
    const p = ctx.params
    if (!liquidEnough(f, p)) return false
    if (f.rsi14 === null || f.rsi14 > p.rsiEntry) return false
    if (p.requireAboveEma50 && (f.ema50 === null || f.close < f.ema50)) return false
    return { reason: `RSI ${f.rsi14.toFixed(1)} with price above the 50-day EMA` }
  },

  exit(f, position, ctx) {
    const p = ctx.params
    if (f.rsi14 !== null && f.rsi14 >= p.rsiExit) {
      return { reason: `RSI recovered to ${f.rsi14.toFixed(1)}` }
    }
    // A mean-reversion trade that has not reverted is a broken thesis, not a
    // long-term hold.
    if (p.maxHoldBars && position.barsHeld >= p.maxHoldBars) {
      return { reason: `Held ${position.barsHeld} bars without reverting` }
    }
    return false
  },

  stopPrice(f, position, ctx) {
    if (f.atr14 === null) return null
    return position.entryPrice - f.atr14 * ctx.params.atrStopMultiple
  },

  targetPrice(f, position, ctx) {
    if (f.atr14 === null) return null
    return position.entryPrice + f.atr14 * ctx.params.targetMultiple
  },
}

/* ==========================================================================
   Sample strategy 3 — trend following
   ========================================================================== */

export const trendStrategy = {
  id: "trend-ema",
  name: "EMA trend following",
  description:
    "Holds while the EMA stack is aligned upward and momentum is positive; exits " +
    "when the stack breaks. Sample strategy — a plain moving-average system.",

  params: {
    minTrendScore: 3,
    requirePositiveMacd: true,
    atrStopMultiple: 3,
    targetMultiple: null,
    minDollarVolume: 5e6,
    minPrice: 3,
  },

  entry(f, ctx) {
    const p = ctx.params
    if (!liquidEnough(f, p)) return false
    if (f.trendScore === null || f.trendScore < p.minTrendScore) return false
    if (p.requirePositiveMacd && (f.macdHistogram === null || f.macdHistogram <= 0)) return false
    return { reason: `EMA stack aligned (score ${f.trendScore}) with positive MACD` }
  },

  exit(f, position, ctx) {
    if (f.trendScore !== null && f.trendScore < 1) {
      return { reason: `Trend score fell to ${f.trendScore}` }
    }
    return false
  },

  stopPrice(f, position, ctx) {
    if (f.atr14 === null) return null
    return position.entryPrice - f.atr14 * ctx.params.atrStopMultiple
  },

  targetPrice() {
    // Trend systems cut losers and let winners run; a fixed target defeats that.
    return null
  },
}

export const STRATEGIES = [breakoutStrategy, meanReversionStrategy, trendStrategy]

export function getStrategy(id) {
  return STRATEGIES.find(s => s.id === id) || null
}

/** Merge caller overrides onto a strategy's defaults without mutating either. */
export function withParams(strategy, overrides) {
  return { ...strategy, params: { ...strategy.params, ...(overrides || {}) } }
}

/* ==========================================================================
   Parameter metadata — what a control for each parameter looks like
   ==========================================================================

   The strategy objects above own the DEFAULTS. This owns the bounds, the
   labels and the explanation, so a UI can render controls for any strategy
   without knowing which strategy it is, and adding a parameter to a strategy
   is one entry here rather than a new form field somewhere else.

   The bounds are not decoration. A parameter box that accepts any number
   invites an ATR multiple of 500 or an RSI entry of 900 — inputs that produce
   a backtest with zero trades and no explanation of why. Every range below is
   the region where the parameter still means what its name says.
   ========================================================================== */

export const PARAM_META = {
  rvolMin: {
    label: "Minimum relative volume",
    type: "number", min: 0.5, max: 5, step: 0.1,
    help: "Volume against the 20-day average. 1.0 is a typical day; above 1.5 is genuine participation.",
  },
  trendScoreMin: {
    label: "Minimum trend score",
    type: "number", min: 0, max: 4, step: 1,
    help: "How much of the EMA stack must be aligned upward, 0 to 4.",
  },
  minTrendScore: {
    label: "Minimum trend score",
    type: "number", min: 0, max: 4, step: 1,
    help: "How much of the EMA stack must be aligned upward, 0 to 4.",
  },
  rsiEntry: {
    label: "RSI entry level",
    type: "number", min: 5, max: 50, step: 1,
    help: "Buy when RSI falls below this. Lower means rarer, deeper pullbacks.",
  },
  rsiExit: {
    label: "RSI exit level",
    type: "number", min: 40, max: 95, step: 1,
    help: "Sell once RSI recovers above this.",
  },
  atrStopMultiple: {
    label: "Stop distance (× ATR)",
    type: "number", min: 0.5, max: 6, step: 0.25,
    help: "Stop placed this many average true ranges below entry. Wider stops are hit less often but cost more when they are.",
  },
  targetMultiple: {
    label: "Profit target (× risk)",
    type: "number", min: 1, max: 12, step: 0.5, nullable: true,
    help: "Take profit at this multiple of the risked amount. Leave empty to let the stop and exit rule decide.",
  },
  maxHoldBars: {
    label: "Maximum bars held",
    type: "number", min: 1, max: 120, step: 1,
    help: "Force an exit after this many bars, whatever the position is doing.",
  },
  minDollarVolume: {
    label: "Minimum dollar volume",
    type: "number", min: 1e5, max: 1e9, step: 1e5, format: "compact",
    help: "Liquidity floor. Below this a fill moves the price against you.",
  },
  minPrice: {
    label: "Minimum share price",
    type: "number", min: 0.5, max: 100, step: 0.5,
    help: "Excludes sub-dollar names, where spreads dominate the result.",
  },
  exitOnTrendLoss: {
    label: "Exit when the trend breaks",
    type: "boolean",
    help: "Close the position as soon as the trend condition stops holding, rather than waiting for the stop.",
  },
  requireAboveEma50: {
    label: "Require price above the 50-day EMA",
    type: "boolean",
    help: "Only buy pullbacks that are still inside an uptrend.",
  },
  requirePositiveMacd: {
    label: "Require positive MACD",
    type: "boolean",
    help: "Demand momentum confirmation alongside the EMA stack.",
  },
}

/**
 * Controls to render for a strategy, in its own declared order.
 *
 * Driven by the strategy's own params object, so a parameter with no metadata
 * is surfaced as a plain number rather than silently disappearing from the UI
 * — an invisible parameter is worse than an unlabelled one.
 */
export function paramControls(strategy) {
  if (!strategy?.params) return []
  return Object.keys(strategy.params).map(key => {
    const meta = PARAM_META[key]
    const value = strategy.params[key]
    return {
      key,
      value,
      label: meta?.label || key,
      help: meta?.help || null,
      type: meta?.type || (typeof value === "boolean" ? "boolean" : "number"),
      min: meta?.min,
      max: meta?.max,
      step: meta?.step ?? 1,
      nullable: meta?.nullable === true,
      format: meta?.format || null,
    }
  })
}

/**
 * Clamp a parameter into its declared range.
 *
 * Returns the value AND whether it had to be changed, because silently
 * correcting somebody's input and then reporting a result computed from a
 * different number is its own kind of lie.
 */
export function clampParam(key, raw) {
  const meta = PARAM_META[key]
  if (!meta) return { value: raw, clamped: false }

  if (meta.type === "boolean") return { value: Boolean(raw), clamped: false }

  if (raw === null || raw === "" || raw === undefined) {
    if (meta.nullable) return { value: null, clamped: false }
    return { value: meta.min ?? 0, clamped: true }
  }

  const n = Number(raw)
  if (!Number.isFinite(n)) return { value: meta.min ?? 0, clamped: true }

  const lo = meta.min ?? -Infinity
  const hi = meta.max ?? Infinity
  const clamped = Math.min(hi, Math.max(lo, n))
  return { value: clamped, clamped: clamped !== n }
}
