import React from "react"

/**
 * An equity curve, drawn from the backtest's own per-bar marks.
 *
 * Two decisions worth stating:
 *
 *  1. THE BASELINE IS STARTING CAPITAL, and it is always inside the drawn
 *     range. A curve auto-scaled to its own min and max makes a strategy that
 *     lost 2% look identical to one that made 200%; the reader cannot tell
 *     whether the line is above water without a reference, so the reference is
 *     drawn.
 *  2. THE AREA IS TINTED FROM THE BASELINE, not from the bottom of the chart,
 *     so the shaded region means "profit" rather than "ink".
 *
 * Pure SVG with a fixed viewBox and preserveAspectRatio="none": no measurement,
 * no refs, identical output on server and client.
 */

const W = 600
const H = 120
const PAD = 3

export default function EquityCurve({ points, initial }) {
  if (!Array.isArray(points) || points.length < 2) {
    return <p className="empty-note">No equity curve: this strategy never held a position.</p>
  }

  const values = points.map(p => p.equity)
  const base = Number.isFinite(initial) ? initial : values[0]

  // The baseline is forced into the domain so it is always visible.
  const lo = Math.min(...values, base)
  const hi = Math.max(...values, base)
  const range = hi - lo || 1

  const x = i => (i / (points.length - 1)) * W
  const y = v => PAD + (1 - (v - lo) / range) * (H - PAD * 2)

  const line = points.map((p, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(2)},${y(p.equity).toFixed(2)}`).join(" ")
  const baseY = y(base)
  const area = `${line} L${W},${baseY.toFixed(2)} L0,${baseY.toFixed(2)} Z`

  const final = values[values.length - 1]
  const totalPct = base > 0 ? ((final - base) / base) * 100 : null

  return (
    <figure className="equity-figure">
      <svg
        className="equity-curve"
        viewBox={`0 0 ${W} ${H}`}
        preserveAspectRatio="none"
        role="img"
        aria-label={
          totalPct === null
            ? "Equity curve"
            : `Equity curve, ${totalPct >= 0 ? "up" : "down"} ${Math.abs(totalPct).toFixed(1)} percent over the test`
        }
      >
        <path className="equity-curve__area" d={area} />
        <line className="equity-curve__baseline" x1="0" x2={W} y1={baseY} y2={baseY} />
        <path className="equity-curve__line" d={line} />
      </svg>
      <figcaption className="equity-figure__caption">
        Dashed line is starting capital. {points.length} marks.
      </figcaption>
    </figure>
  )
}
