/**
 * Running a backtest in the browser, against edited parameters.
 *
 * Until now every backtest on this site was computed at build time by
 * scripts/engine/snapshot.mjs and read back as a frozen result. That made
 * /strategies/ a report rather than a tool: you could see what the engine
 * concluded, but you could not ask it a different question.
 *
 * WHY THIS CAN RUN CLIENT-SIDE AT ALL
 * backtest.js imports only features.js, which imports only vwap.js, and
 * metrics.js imports nothing. None of that chain touches the filesystem. The
 * modules that DO — optimizer.js and walkforward.js, both of which reach
 * store.js — are deliberately not used here, so parameter search and
 * walk-forward remain build-time work. Those are the expensive, long-running
 * passes; a single backtest is not.
 *
 * WHAT THIS DELIBERATELY DOES NOT CLAIM
 * A result produced here is IN-SAMPLE. The user picked the parameters after
 * seeing the data, which is the definition of the overfitting this page exists
 * to warn about. The baseline in the snapshot survived a walk-forward test; an
 * ad-hoc run has survived nothing. Every result carries `inSample: true` so the
 * UI is unable to present one as though it were evidence — the honest framing
 * has to be structural, not a note somebody might forget to render.
 */

import { runPortfolioBacktest } from "./portfolioBacktest.js"
import { analyze } from "./metrics.js"
import { getStrategy, withParams, clampParam } from "./strategy.js"
import { generateCandles } from "../data/candles.js"

/**
 * Bars for the universe, memoised for the life of the page.
 *
 * Building 14 five-year series is the slowest part of a run by some distance,
 * and the bars do not change between parameter tweaks — only the strategy
 * reading them does. Without this, every click would pay for the data again.
 */
const barCache = new Map()

function loadBars(symbols, timeframe) {
  const key = `${timeframe}:${symbols.join(",")}`
  if (barCache.has(key)) return barCache.get(key)

  const bars = {}
  for (const symbol of symbols) {
    try {
      const series = generateCandles(symbol, timeframe)
      if (Array.isArray(series) && series.length) bars[symbol] = series
    } catch {
      // A symbol with no series is dropped rather than fatal: one bad ticker
      // should not make the whole page unable to run anything.
    }
  }

  barCache.set(key, bars)
  return bars
}

/** Drop the cache — used when the underlying data is swapped from Supabase. */
export function resetBarCache() {
  barCache.clear()
}

/**
 * Normalise user input into parameters the engine will accept.
 *
 * Returns the clamped values and the keys that had to be corrected, so the UI
 * can say "that was out of range and I used 5" rather than quietly running
 * something other than what was typed.
 */
export function sanitiseParams(strategy, edited) {
  const params = {}
  const clamped = []

  for (const key of Object.keys(strategy.params)) {
    const raw = edited && key in edited ? edited[key] : strategy.params[key]
    const result = clampParam(key, raw)
    params[key] = result.value
    if (result.clamped) clamped.push(key)
  }

  return { params, clamped }
}

/** Has the user actually changed anything from the strategy's defaults? */
export function isModified(strategy, params) {
  if (!params) return false
  return Object.keys(strategy.params).some(key => params[key] !== strategy.params[key])
}

/**
 * Run one backtest and summarise it.
 *
 * Synchronous on purpose. A portfolio pass over fourteen symbols is tens of
 * milliseconds — fast enough that a worker, its message plumbing and its
 * separate copy of the module graph would cost more than they saved, and would
 * make the numbers harder to prove identical to the build-time ones.
 */
export function runBacktest({ strategyId, params, symbols, timeframe = "5Y", config }) {
  const base = getStrategy(strategyId)
  if (!base) throw new Error(`No strategy with id "${strategyId}"`)

  const { params: clean, clamped } = sanitiseParams(base, params)
  const strategy = withParams(base, clean)

  const bars = loadBars(symbols, timeframe)
  const tradable = symbols.filter(s => Array.isArray(bars[s]) && bars[s].length > 60)

  if (!tradable.length) {
    return {
      ok: false,
      reason: "no-data",
      message: "No symbol has enough history to backtest at this timeframe.",
    }
  }

  /*
   * runPortfolioBacktest, NOT backtest.js's backtestPortfolio.
   *
   * They are different models and they disagree: the simple one gives each
   * symbol its own slice of cash and runs them independently, while this one
   * simulates a single account, so trades compete for capital and some are
   * refused. On this universe that is 74 trades against 98, and +15.5% against
   * +1.9%.
   *
   * The baseline shown beside these results was produced at build time by
   * runPortfolioBacktest. Using the other one here would mean the "before" and
   * "after" columns came from different simulators — a comparison that looks
   * precise and means nothing.
   */
  const started = Date.now()
  const result = runPortfolioBacktest({
    symbols: tradable,
    barsBySymbol: bars,
    strategy,
    params: clean,
    ...(config || {}),
  })
  const analysis = analyze(result)

  return {
    ok: true,
    /*
     * The flag the UI cannot ignore. These parameters were chosen while
     * looking at this data, so the result describes the past rather than
     * predicting anything. The snapshot baseline is the one with an
     * out-of-sample claim behind it.
     */
    inSample: true,
    modified: isModified(base, clean),
    clamped,
    strategyId,
    params: clean,
    symbols: tradable,
    skipped: symbols.filter(s => !tradable.includes(s)),
    timeframe,
    analysis,
    equityCurve: result.equityCurve,
    trades: result.trades,
    tookMs: Date.now() - started,
  }
}

/**
 * The comparable figures from a snapshot backtest.
 *
 * The build-time entry and a live run report the same quantities under
 * different shapes, and the page puts them side by side. Reading both through
 * one function is what stops a column comparing net return against gross, or a
 * percentage against a ratio.
 */
export function baselineMetrics(entry) {
  if (!entry) return null
  /*
   * The snapshot calls it `stats`, a live run calls it `analysis`, and the two
   * objects overlap rather than match — analyze() returns a superset. Pulling
   * both through one reader is what stops a comparison column putting net
   * return against gross, or a rate against a percentage.
   */
  const a = entry.stats || entry.analysis || entry
  return {
    trades: a.trades ?? null,
    totalReturnPct: a.totalReturnPct ?? null,
    maxDrawdownPct: a.maxDrawdownPct ?? null,
    winRate: a.winRate ?? null,
    profitFactor: a.profitFactor ?? null,
    expectancy: a.expectancy ?? null,
    sharpe: a.sharpe ?? null,
    netPnl: a.netPnl ?? null,
  }
}
