/**
 * Signal scoring — the pure arithmetic, with no filesystem behind it.
 *
 * Split out of signals.js so it can run in a browser.
 *
 * signals.js imports store.js to persist and query signals, and store.js needs
 * node:fs and node:crypto. That is correct for what signals.js does, and it
 * makes the whole module unimportable in a bundle. But portfolioBacktest.js
 * needs only scoreSignal() and WARMUP_BARS — neither of which touches a disk —
 * so the Node-only dependency was reaching the browser purely by being in the
 * same file as the thing that was wanted.
 *
 * Nothing here changed in the move. signals.js re-exports these, so its public
 * surface is unchanged and every existing caller keeps working; the scores are
 * the same numbers computed by the same code, which is what makes a backtest
 * run in the browser comparable with one run at build time.
 */

/**
 * Indicators need a run-up before they exist. Evaluating a strategy at bar 3
 * does not produce "no signal", it produces a decision made on nulls — which
 * looks like no signal and quietly biases every sample that includes it.
 * 50 bars clears EMA50, RSI14 and MACD; EMA200 is still warming and is treated
 * as unavailable rather than assumed.
 */
export const WARMUP_BARS = 50

/* ==========================================================================
   Schema
   ========================================================================== */

/**
 * Every field on a signal record, in record order. Records are built through
 * buildSignal() alone, so this list is exhaustive by construction — there is no
 * second place that can add a field and forget to document it.
 */
export const SIGNAL_FIELD_META = [
  { key: "id", type: "string", description: "makeId(\"sig\", [symbol, strategyId, time]) — the idempotency key." },
  { key: "schemaVersion", type: "number", description: "Record shape version; matches SCHEMAS.signals." },
  { key: "symbol", type: "string", description: "Ticker." },
  { key: "time", type: "number", description: "Signal bar's close time, unix SECONDS." },
  { key: "timeISO", type: "string", description: "Same instant as an ISO-8601 string, for humans." },
  { key: "strategyId", type: "string", description: "Strategy that fired." },
  { key: "strategyName", type: "string", description: "Its display name at generation time." },
  { key: "direction", type: "string", description: "\"long\" | \"short\"." },
  { key: "trigger", type: "string", description: "The human reason the strategy returned." },
  { key: "price", type: "number", description: "Close of the signal bar — observed, NOT a fill price." },
  { key: "barIndex", type: "number", description: "Index into the bar array the scan ran over." },
  { key: "score", type: "number", description: "0-100 composite from scoreSignal()." },
  { key: "scoreComponents", type: "object", description: "Per-component breakdown, including which inputs were unavailable." },
  { key: "rank", type: "number|null", description: "Position within a ranked batch; null until rankSignals() runs." },
  { key: "features", type: "object", description: "The FULL feature vector at the signal bar — what makes reconstruction possible." },
  { key: "params", type: "object", description: "Strategy parameters in force for this evaluation." },
  { key: "metadata", type: "object", description: "{ dataSource, dataIsReal, timeframe, generatedWith, paramsHash, barCount }." },
]

/** Field names only — the list tests assert a record against. */
export const SIGNAL_SCHEMA_FIELDS = SIGNAL_FIELD_META.map(f => f.key)

/* ==========================================================================
   Scoring
   ==========================================================================

   A composite of four things, all of which a discretionary trader would look at
   before taking a signal: is the trend behind it, is momentum behind it, did
   volume show up, and how decisively did it clear the level.

   WEIGHTS (sum to 1.00, and that is asserted at module load):

     trend           0.30   trendScore, the EMA stack
     momentumRsi     0.18 ┐ 0.30 momentum, split so that one missing input
     momentumMacd    0.12 ┘ does not take the whole momentum term with it
     relativeVolume  0.25   rvol — participation, the hardest of the four to fake
     breakout        0.15   how far past the prior level it closed

   Every component is normalised to 0..1 against STATED bounds and then
   weighted. Bounds are deliberately tight: a 3x rvol and a 10x rvol are both
   "huge", and letting the 10x run away with the score would make one component
   the whole number.

   NULLS DO NOT POISON THE SCORE. A component whose input is unavailable scores
   the neutral 0.5 and is recorded in `unavailable`. `neutralWeight` reports how
   much of the score was that fallback, so a 72 built on two missing inputs is
   visibly weaker evidence than a 72 built on four present ones. Neutral is NOT
   zero: scoring a missing input as 0 would read as bearish evidence that was
   never observed.
   ========================================================================== */

function clamp01(x) {
  if (x < 0) return 0
  if (x > 1) return 1
  return x
}

export function isNum(v) {
  return typeof v === "number" && Number.isFinite(v)
}

/**
 * Percentage distance between two prices. Not an indicator — just a ratio of
 * two values features.js already produced.
 */
function pctDistance(from, to) {
  if (!isNum(from) || !isNum(to) || from === 0) return null
  return ((to - from) / Math.abs(from)) * 100
}

/**
 * The component table. Each entry states its bounds in prose AND implements
 * them, so the documentation cannot drift from the arithmetic.
 *
 * `value(f, direction)` returns { raw, norm } with norm already oriented for
 * the direction: 1 always means "maximally supportive of THIS signal".
 */
const SCORE_COMPONENTS = [
  {
    key: "trend",
    label: "Trend strength",
    feature: "trendScore",
    weight: 0.3,
    bounds: "trendScore -3 → 0.0, 0 → 0.5, +3 → 1.0 (inverted for shorts)",
    value(f, direction) {
      const v = f.trendScore
      if (!isNum(v)) return { raw: null, norm: null }
      const norm = clamp01((v + 3) / 6)
      return { raw: v, norm: direction === "short" ? 1 - norm : norm }
    },
  },
  {
    key: "momentumRsi",
    label: "Momentum (RSI distance from 50)",
    feature: "rsi14",
    weight: 0.18,
    bounds: "RSI 20 → 0.0, 50 → 0.5, 80 → 1.0, clamped (inverted for shorts)",
    value(f, direction) {
      const v = f.rsi14
      if (!isNum(v)) return { raw: null, norm: null }
      const norm = clamp01((v - 20) / 60)
      return { raw: v, norm: direction === "short" ? 1 - norm : norm }
    },
  },
  {
    key: "momentumMacd",
    label: "Momentum (MACD histogram sign)",
    feature: "macdHistogram",
    weight: 0.12,
    bounds:
      "sign only: >0 → 1.0, =0 → 0.5, <0 → 0.0 (inverted for shorts). The magnitude is in " +
      "price units and is not comparable across symbols, so only the sign is used.",
    value(f, direction) {
      const v = f.macdHistogram
      if (!isNum(v)) return { raw: null, norm: null }
      const norm = v > 0 ? 1 : v < 0 ? 0 : 0.5
      return { raw: v, norm: direction === "short" ? 1 - norm : norm }
    },
  },
  {
    key: "relativeVolume",
    label: "Relative volume",
    feature: "rvol",
    weight: 0.25,
    bounds:
      "rvol 0.5 → 0.0, 1.0 → 0.2, 3.0+ → 1.0, clamped. Direction-neutral: participation " +
      "confirms a move either way.",
    value(f) {
      const v = f.rvol
      if (!isNum(v)) return { raw: null, norm: null }
      return { raw: v, norm: clamp01((v - 0.5) / 2.5) }
    },
  },
  {
    key: "breakout",
    label: "Breakout margin",
    feature: "breakoutMargin",
    weight: 0.15,
    bounds:
      "long: % over the prior 20-day high, -2% → 0.0, 0% → 0.29, +5% → 1.0. " +
      "short: % under the prior 20-day low on the same scale, measured from priorLow20.",
    value(f, direction) {
      if (direction === "short") {
        // There is no breakdownMargin feature yet, so the short side measures
        // the same thing against the prior low from two features that already
        // exist. Below the low is negative, so the scale is reversed.
        const raw = pctDistance(f.priorLow20, f.close)
        if (raw === null) return { raw: null, norm: null }
        return { raw, norm: clamp01((2 - raw) / 7) }
      }
      const raw = f.breakoutMargin
      if (!isNum(raw)) return { raw: null, norm: null }
      return { raw, norm: clamp01((raw + 2) / 7) }
    },
  },
]

/** Published weights, for the UI and for tests that assert the documented mix. */
export const SCORE_WEIGHTS = Object.freeze(
  SCORE_COMPONENTS.reduce((acc, c) => {
    acc[c.key] = c.weight
    return acc
  }, {})
)

// A silent weight drift would rescale every stored score without changing a
// single documented number. Fail loudly at import instead.
{
  const total = SCORE_COMPONENTS.reduce((s, c) => s + c.weight, 0)
  if (Math.abs(total - 1) > 1e-9) {
    throw new Error(`Signal score weights must sum to 1, got ${total}`)
  }
}

const NEUTRAL = 0.5

export function round(value, places) {
  const f = 10 ** places
  return Math.round(value * f) / f
}

/**
 * The 0-100 composite for one feature vector.
 *
 * @param {object} features  a vector from features.js
 * @param {string} [direction] "long" (default) or "short" — flips the
 *        directional components so 100 always means "strongly supports THIS
 *        signal", never "strongly bullish".
 * @returns {object} {
 *   score            0-100, or null if `features` is not a vector
 *   direction
 *   components[]     { key, label, feature, weight, bounds, raw, normalised,
 *                      available, contribution }
 *   unavailable[]    component keys that fell back to neutral
 *   neutralWeight    share of the score that came from that fallback, 0..1
 *   coverage         1 - neutralWeight; how much of the score was measured
 * }
 */
export function scoreSignal(features, direction = "long") {
  const dir = direction === "short" ? "short" : "long"

  if (!features || typeof features !== "object") {
    return {
      score: null,
      direction: dir,
      components: [],
      unavailable: SCORE_COMPONENTS.map(c => c.key),
      neutralWeight: 1,
      coverage: 0,
    }
  }

  const components = []
  const unavailable = []
  let total = 0
  let neutralWeight = 0

  for (const spec of SCORE_COMPONENTS) {
    const { raw, norm } = spec.value(features, dir)
    const available = norm !== null
    const effective = available ? norm : NEUTRAL
    if (!available) {
      unavailable.push(spec.key)
      neutralWeight += spec.weight
    }
    total += spec.weight * effective
    components.push({
      key: spec.key,
      label: spec.label,
      feature: spec.feature,
      weight: spec.weight,
      bounds: spec.bounds,
      raw: available ? round(raw, 6) : null,
      normalised: round(effective, 6),
      available,
      contribution: round(spec.weight * effective * 100, 4),
    })
  }

  return {
    score: round(total * 100, 2),
    direction: dir,
    components,
    unavailable,
    neutralWeight: round(neutralWeight, 6),
    coverage: round(1 - neutralWeight, 6),
  }
}
