import React, { useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import DataStatus from "../components/engine/DataStatus"
import Toast, { useToast } from "../components/ui/Toast"
import EquityCurve from "../components/engine/EquityCurve"
import StrategyLab from "../components/engine/StrategyLab"

import {
  backtests, optimisations, walkForwards, universe, barCount, timeframe, source, generatedAt,
} from "../data/generated/engine-snapshot"

/**
 * Strategies.
 *
 * Backtest results, the parameter search that produced them, and the
 * walk-forward test that says whether any of it generalises.
 *
 * THE EDITORIAL LINE OF THIS PAGE: an in-sample number is not evidence. The
 * optimiser's best result was SELECTED to look good, and will always look good.
 * The only figure here worth trusting is out-of-sample consistency, and it is
 * given the most prominent position on the page for exactly that reason —
 * above the headline return, not below it in a footnote.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)

const num = (v, d = 2) => (isNum(v) ? v.toFixed(d) : DASH)
const pct = (v, d = 1) => (isNum(v) ? (v > 0 ? "+" : "") + v.toFixed(d) + "%" : DASH)
const usd = v => (isNum(v) ? (v < 0 ? "−$" : "$") + Math.abs(v).toFixed(0) : DASH)

function tone(v) {
  if (!isNum(v)) return ""
  return v > 0 ? " strategy-card__metric-value--up" : v < 0 ? " strategy-card__metric-value--down" : ""
}

function paramText(params) {
  if (!params) return DASH
  return Object.entries(params).map(([k, v]) => `${k}=${v}`).join("  ")
}

export default function StrategiesPage({ location }) {
  const { toast, show: showToast, dismiss: dismissToast } = useToast()
  const [openId, setOpenId] = useState(backtests[0]?.strategyId ?? null)

  const detail = useMemo(() => backtests.find(b => b.strategyId === openId) ?? null, [openId])
  const wf = useMemo(() => walkForwards.find(w => w.strategyId === openId) ?? null, [openId])
  const opt = useMemo(() => optimisations.find(o => o.strategyId === openId) ?? null, [openId])

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Strategies" }]} />
            <h1 className="page__title">Strategies</h1>
            <p className="page__lede">
              Three sample strategies, backtested as one book over{" "}
              {universe.tradable.length} symbols and {barCount} bars, then walked forward.
            </p>
          </div>
          <div className="page__meta">
            <span className="page__meta-item">
              <span className="page__meta-label">Data</span>
              <DataStatus source={source} onLocked={() => showToast(source.lockNote)} />
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Window</span>
              <span className="page__meta-value">
                {barCount} {timeframe} bars
              </span>
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Built</span>
              <span className="page__meta-value">{generatedAt.slice(0, 10)}</span>
            </span>
          </div>
        </header>

        <div className="notice">
          <div>
            <p className="notice__title">These are sample strategies, not recommendations</p>
            <p className="notice__text">
              They exist to exercise the engine end to end and to give the walk-forward machinery
              something real to test. They are textbook rules with no edge claim attached, they
              have not been traded, and their parameters were chosen to be legible rather than
              profitable.
            </p>
            <p className="notice__text">
              Costs are charged on every fill — commission and slippage — and every position is
              liquidated at the end, so nothing here is flattered by an open winner.
            </p>
          </div>
        </div>

        <Panel title="Results" subtitle="One book, one pool of cash. Signals compete for it.">
          <div className="strategy-grid">
            {backtests.map(bt => {
              const forward = walkForwards.find(w => w.strategyId === bt.strategyId)
              const consistency = forward?.aggregate?.consistency
              return (
                <article
                  className={"strategy-card" + (bt.strategyId === openId ? " is-open" : "")}
                  key={bt.strategyId}
                >
                  <header className="strategy-card__head">
                    <h3 className="strategy-card__name">{bt.strategyName}</h3>
                    <span className="strategy-card__sample">Sample</span>
                    <p className="strategy-card__desc">{bt.description}</p>
                  </header>

                  <div className="strategy-card__metrics">
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Out-of-sample</span>
                      <span className={"strategy-card__metric-value" + tone(isNum(consistency) ? consistency - 50 : null)}>
                        {isNum(consistency) ? consistency.toFixed(0) + "%" : DASH}
                      </span>
                    </div>
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Trades</span>
                      <span className="strategy-card__metric-value">{bt.stats.trades}</span>
                    </div>
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Return</span>
                      <span className={"strategy-card__metric-value" + tone(bt.stats.totalReturnPct)}>
                        {pct(bt.stats.totalReturnPct)}
                      </span>
                    </div>
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Win rate</span>
                      <span className="strategy-card__metric-value">{num(bt.stats.winRate, 0)}%</span>
                    </div>
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Expectancy</span>
                      <span className={"strategy-card__metric-value" + tone(bt.stats.expectancy)}>
                        {usd(bt.stats.expectancy)}
                      </span>
                    </div>
                    <div className="strategy-card__metric">
                      <span className="strategy-card__metric-label">Max DD</span>
                      <span className="strategy-card__metric-value">{num(bt.stats.maxDrawdownPct, 1)}%</span>
                    </div>
                  </div>

                  <div className="strategy-card__body">
                    <EquityCurve points={bt.equityCurve} initial={bt.equityCurve[0]?.equity} />

                    {bt.stats.caveats?.length > 0 && (
                      <ul className="strategy-card__caveats">
                        {bt.stats.caveats.map((c, i) => (
                          <li key={i}>{c}</li>
                        ))}
                      </ul>
                    )}

                    <button
                      type="button"
                      className="coverage__toggle"
                      onClick={() => setOpenId(bt.strategyId === openId ? null : bt.strategyId)}
                      style={{ marginLeft: 0, marginTop: 12 }}
                    >
                      {bt.strategyId === openId ? "Hide detail" : "Detail"}
                    </button>
                  </div>
                </article>
              )
            })}
          </div>
        </Panel>

        <StrategyLab
          backtests={backtests}
          symbols={universe.tradable}
          timeframe={timeframe}
          onNotice={showToast}
        />

        {wf && <WalkForwardPanel wf={wf} />}
        {opt && <OptimisationPanel opt={opt} />}
        {detail && <ContentionPanel bt={detail} />}
      </div>
      <Toast toast={toast} onDismiss={dismissToast} />
    </Shell>
  )
}

/* -------------------------------------------------------------------------- */

function WalkForwardPanel({ wf }) {
  const a = wf.aggregate
  if (!wf.windows.length) {
    return (
      <Panel title={`Walk-forward — ${wf.strategyName}`}>
        <p className="empty-note">{wf.note || "Not enough history to build a single window."}</p>
      </Panel>
    )
  }

  return (
    <Panel
      title={`Walk-forward — ${wf.strategyName}`}
      subtitle={
        `Parameters are chosen on ${wf.config.trainBars} bars and then judged on the ` +
        `${wf.config.testBars} that follow, which the search never saw.`
      }
    >
      <div className="wf-consistency">
        <span className="wf-consistency__value">
          {isNum(a.consistency) ? a.consistency.toFixed(0) + "%" : DASH}
        </span>
        <span className="wf-consistency__label">
          of forward windows were profitable ({a.positiveWindows} up / {a.negativeWindows} down,
          {" "}{a.outOfSampleTrades} out-of-sample trades). This is the number that matters. A
          strategy that optimises beautifully and wins half its forward windows has learned noise.
        </span>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table className="wf-table">
          <thead>
            <tr>
              <th>#</th>
              <th>Train</th>
              <th>Test</th>
              <th>Chosen in-sample</th>
              <th className="num">OOS trades</th>
              <th className="num">OOS return</th>
              <th className="num">Max DD</th>
            </tr>
          </thead>
          <tbody>
            {wf.windows.map(w => (
              <tr key={w.index}>
                <td className="num">{w.index}</td>
                <td className="num">
                  {w.trainStart}–{w.trainEnd}
                </td>
                <td className="num">
                  {w.testStart}–{w.testEnd}
                </td>
                <td className="wf-table__params">{paramText(w.chosenParams)}</td>
                <td className="num">{w.test ? w.test.trades : 0}</td>
                <td className="num">
                  <span
                    className={
                      w.test && isNum(w.test.totalReturnPct)
                        ? "delta " + (w.test.totalReturnPct >= 0 ? "delta--up" : "delta--down")
                        : ""
                    }
                  >
                    {w.test ? pct(w.test.totalReturnPct, 2) : DASH}
                  </span>
                </td>
                <td className="num">{w.test ? num(w.test.maxDrawdownPct, 1) + "%" : DASH}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="empty-note" style={{ marginTop: 16 }}>
        Each test slice carries {wf.config.warmUpBars} bars of training data purely so the
        indicators exist at its first bar. No trade may be opened on those bars, and none of their
        outcomes are counted — the backtester is given the offset explicitly and enforces it.
      </p>
    </Panel>
  )
}

function OptimisationPanel({ opt }) {
  return (
    <Panel
      title={`Parameter search — ${opt.strategyName}`}
      subtitle={
        `${opt.combinations} combinations scored on ${opt.objectiveLabel}. ` +
        `${opt.scoreable} produced a large enough sample to score at all.`
      }
    >
      <div className="notice notice--info" style={{ marginBottom: 16 }}>
        <div>
          <p className="notice__title">Read this table as a sensitivity check, not a result</p>
          <p className="notice__text">
            The winning row was chosen by looking at the whole period, so its numbers are
            in-sample and will always flatter it. What the table is genuinely good for is the
            spread: a strategy whose top and bottom rows are close is robust to its parameters,
            and one where a single cell towers over its neighbours has found a coincidence.
          </p>
        </div>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table className="wf-table">
          <thead>
            <tr>
              <th>Parameters</th>
              <th className="num">Score</th>
              <th className="num">Trades</th>
              <th className="num">Return</th>
              <th className="num">Max DD</th>
              <th className="num">Win rate</th>
              <th className="num">Profit factor</th>
            </tr>
          </thead>
          <tbody>
            {opt.candidates.map((c, i) => (
              <tr key={i} className={i === 0 ? "is-best" : ""}>
                <td className="wf-table__params">{paramText(c.params)}</td>
                <td className="num">{isNum(c.score) ? num(c.score, 3) : <span className="muted">unscoreable</span>}</td>
                <td className="num">{c.trades}</td>
                <td className="num">{pct(c.totalReturnPct, 2)}</td>
                <td className="num">{num(c.maxDrawdownPct, 1)}%</td>
                <td className="num">{num(c.winRate, 0)}%</td>
                <td className="num">{isNum(c.profitFactor) ? num(c.profitFactor) : DASH}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Panel>
  )
}

function ContentionPanel({ bt }) {
  const total = bt.contention.totalCandidates
  return (
    <Panel
      title={`What did NOT trade — ${bt.strategyName}`}
      subtitle={
        `${total} entry candidates competed for one pool of cash. ${bt.contention.admitted} were ` +
        `funded; ${bt.contention.rejected} were refused, each with a reason.`
      }
    >
      {bt.rejectionCodes.length === 0 ? (
        <p className="empty-note">
          Nothing was refused: every signal this strategy produced could be funded within the
          limits.
        </p>
      ) : (
        <>
          <ul className="risk-list">
            {bt.rejectionCodes.map(r => (
              <li className="risk-list__item" key={r.code}>
                <span className="risk-list__symbol">{r.count}</span>
                <span className="risk-list__reason">
                  <span className="risk-list__code risk-list__code--refused">{r.code}</span>
                  <br />
                  {CODE_NOTES[r.code] || "Refused by a portfolio or risk limit."}
                </span>
                <span className="risk-list__size">
                  {((r.count / total) * 100).toFixed(0)}%<small>of candidates</small>
                </span>
              </li>
            ))}
          </ul>
          <p className="empty-note" style={{ marginTop: 16 }}>
            A backtest that silently dropped these would overstate nothing, but it would hide why
            it traded what it traded — and a limit quietly eating the best signals is
            indistinguishable from a strategy that produced none.
          </p>
        </>
      )}

      {bt.notes.length > 0 && (
        <ul className="strategy-card__caveats" style={{ marginTop: 16 }}>
          {bt.notes.map((n, i) => (
            <li key={i}>{n}</li>
          ))}
        </ul>
      )}
    </Panel>
  )
}

const CODE_NOTES = {
  MAX_POSITIONS: "The book already held the maximum number of simultaneous positions.",
  MAX_EXPOSURE: "Funding it would have taken total invested capital past the exposure ceiling.",
  MAX_CONCENTRATION: "A single position would have been too large a share of equity.",
  INSUFFICIENT_CASH: "Not enough cash to buy even one share including commission.",
  SIZE_ZERO: "The risk budget divided by the stop distance rounded to zero shares.",
  ALREADY_OPEN: "A position in this symbol was already open; adding would double the risk.",
  NO_STOP: "No stop price, so risk-based sizing is undefined and the trade cannot be sized.",
  STOP_TOO_TIGHT: "The stop sat inside the noise floor; ordinary range would have filled it.",
  NO_FILL_BAR: "Signalled on its final bar, so there was never a following open to fill at.",
  KILL_SWITCH_TRIPPED: "Trading was halted by a drawdown or daily-loss limit.",
  MAX_DRAWDOWN: "Peak-to-trough decline had reached the configured limit.",
  MAX_DAILY_LOSS: "The day's loss limit had been reached.",
}

export const Head = () => <title>Strategies · MarketScan</title>
