import React from "react"

import LockBadge from "../ui/LockBadge"
import { useDataVersion } from "../data/DataProvider"
import { describeSource } from "../../data/source.js"
import { dataOrigin, ORIGIN } from "../../data/store.js"

/**
 * The data-provenance strip.
 *
 * Reads "Massive · End-of-day · 14-symbol universe · Ingested Sep 20".
 *
 * Every part comes from the data itself rather than from a literal: the symbol
 * count is the number of ingested series, and the date is the timestamp the
 * ingest wrote. A hardcoded date on a provenance strip is worse than no date —
 * it is a claim that goes quietly false the first time anyone refreshes, and
 * provenance is exactly the thing a client checks.
 *
 * WHY IT TAKES A SOURCE PROP AND ALSO IGNORES IT
 * Pages pass the source computed at build time, baked into the engine snapshot.
 * That is the right answer for the first paint, and it is what the server
 * rendered — so using it on the client's first render keeps hydration matching.
 *
 * But once data has been adopted from Supabase, the build-time stamp is no
 * longer the truth: the last ingest may have happened minutes ago, from a
 * browser, with no rebuild in between. That is the entire point of moving
 * ingestion to Supabase, and a strip still quoting the build date would be
 * precisely the stale claim this component exists to avoid. So after a swap it
 * recomputes from live data instead.
 */
export default function DataStatus({ source: buildTimeSource, onLocked = () => {}, title }) {
  /*
   * Subscribes to the store so a data swap re-renders this strip. Without it
   * the date would only update when something else on the page happened to
   * re-render — which is to say, unpredictably.
   */
  useDataVersion()

  const source = dataOrigin() === ORIGIN.SUPABASE ? describeSource() : buildTimeSource

  if (!source) return null

  if (!source.real) {
    return (
      <span className="data-status data-status--demo" title={source.detail}>
        {source.label}
      </span>
    )
  }

  const [venue, cadence, universe, ingested] = source.parts

  return (
    <span className="data-status" title={title || source.detail}>
      <span className="data-status__venue">{venue}</span>
      <span className="data-status__sep">·</span>
      <span className="data-status__cadence">
        {cadence}
        <LockBadge label="End-of-day data" onActivate={onLocked} />
      </span>
      <span className="data-status__sep">·</span>
      <span>{universe}</span>
      <span className="data-status__sep">·</span>
      <span
        className="data-status__ingested"
        /* The full stamp on hover, so "Sep 20" can be checked to the minute. */
        title={source.ingestedAt ? `Ingested ${source.ingestedAt}` : undefined}
      >
        {ingested}
      </span>
    </span>
  )
}
